export const microQuestionPool: MicroQuestion[] = [
  // ── Domain: basic-concepts · micro-scarcity-marginal-analysis ──────────────────
  { question: 'A city council uses its last vacant lot to build a parking garage. Residents had ranked a park as their second choice for the lot and a library as their third. What is the opportunity cost of the garage?', options: ['Both forgone uses combined', 'The park that was ranked second', 'The money spent to build it', 'The third-ranked library'], correctAnswer: 1, explanation: 'Opportunity cost is the value of the single next-best alternative given up, which is the park. It does not add together both forgone uses, the construction spending is an outlay rather than the forgone use of the lot, and the library ranks below the park.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'A coffee shop stays open longer each day as long as it pays. Every hour through the 11th adds more revenue than cost, but the 12th hour would add \\$50 in revenue and \\$60 in cost. How many hours should the shop stay open to maximize profit?', options: ['12 hours per day', '10 hours per day', '11 hours per day', '13 hours per day'], correctAnswer: 2, explanation: 'Each hour through the 11th has marginal revenue above marginal cost, so it adds to profit, while the 12th hour would lose \\$10. Stopping at 10 hours gives up a profitable hour, and staying open 12 or 13 hours adds hours whose cost exceeds their revenue.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'A software firm has already spent \\$2 million developing an app. Finishing it would cost another \\$500,000, and the finished app is expected to earn \\$400,000 in revenue. A rational manager should', options: ['stop development, as finishing costs more than it would earn', 'complete the app so the \\$2 million spent is not wasted', 'finish the app, as revenue exceeds the remaining cost', 'drop the project, as the \\$2 million can never be recovered'], correctAnswer: 0, explanation: 'The \\$2 million is a sunk cost and is irrelevant; the forward-looking comparison is \\$500,000 of added cost against \\$400,000 of added revenue, so the firm should stop. Finishing to avoid "wasting" the \\$2 million is the sunk-cost fallacy, the remaining cost is larger than the revenue, and dropping the app is right but not because of the money already spent.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'Lena spends her whole budget on books at \\$10 each and movie tickets at \\$15 each. For the last unit of each she bought, the marginal utility of a book is 40 and of a ticket is 45. To raise her total utility, Lena should', options: ['shift spending toward tickets and away from books', 'shift spending so she buys equal numbers of each', 'keep her current mix of books and movie tickets', 'shift spending toward books and away from tickets'], correctAnswer: 3, explanation: 'Marginal utility per dollar is 40 ÷ 10 = 4 for books and 45 ÷ 15 = 3 for tickets, so a dollar moved from tickets to books raises total utility. Tickets have the higher total MU per unit but the lower MU per dollar, equal quantities ignore the prices, and her current mix is not optimal because the ratios are unequal.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'Sam\'s total utility from slices of pizza is 20 after one slice, 35 after two, 45 after three, and 50 after four. This pattern shows that', options: ['total utility decreases as Sam eats additional slices', 'marginal utility increases as Sam eats more slices', 'marginal utility stays constant after one slice', 'marginal utility falls as Sam eats more slices'], correctAnswer: 3, explanation: 'The extra utility from each slice is 20, 15, 10, and 5, so marginal utility is diminishing. Total utility is still rising, the additions are shrinking rather than growing, and they change with every slice rather than staying constant.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'A consumer is maximizing utility while buying two goods. Good X costs \\$2 and the marginal utility of the last unit of X is 12. Good Y costs \\$3. What must the marginal utility of the last unit of Y be?', options: ['12 utils', '8 utils', '18 utils', '36 utils'], correctAnswer: 2, explanation: 'Utility maximization requires MU per dollar to be equal: 12 ÷ 2 = 6, so Y needs MU ÷ 3 = 6, or 18 utils. Twelve utils ignores the difference in prices, 8 utils inverts the price ratio, and 36 utils multiplies the prices instead of dividing.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'A town is deciding how many streetlights to install on a dark road. Total benefit is \\$500 for one light, \\$900 for two, \\$1,200 for three, and \\$1,350 for four. Each light costs \\$250. How many lights should the town install?', options: ['4 streetlights', '3 streetlights', '2 streetlights', '1 streetlight'], correctAnswer: 1, explanation: 'Marginal benefits are \\$500, \\$400, \\$300, and \\$150, so the first three lights each add more than their \\$250 cost and the fourth does not. Four lights maximizes total benefit but ignores cost, while stopping at one or two lights leaves units with MB above MC uninstalled.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'Which of the following should NOT influence a bakery\'s decision about whether to bake one more batch of bread today?', options: ['The rent it already paid for this month', 'The flour and yeast used in the extra batch', 'The revenue the extra batch is expected to earn', 'The overtime wages needed to bake the batch'], correctAnswer: 0, explanation: 'Rent already paid is a sunk cost that is the same whether or not the batch is baked, so it does not belong in a marginal decision. The ingredients, the overtime wages, and the extra revenue all change with the decision, so each is part of the marginal comparison.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'How does diminishing marginal utility help explain why demand curves slope downward?', options: ['Sellers cut prices as their costs fall with larger output', 'Buyers have less income left as they purchase more units', 'Buyers will pay less for extra units that add less satisfaction', 'Each extra unit gives buyers more satisfaction than the last'], correctAnswer: 2, explanation: 'If each additional unit adds less satisfaction, a buyer\'s willingness to pay for it falls, so larger quantities are bought only at lower prices. Falling seller costs describe supply, not demand; shrinking leftover income is not the utility argument; and rising satisfaction per unit is the opposite of diminishing marginal utility.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'On a country\'s production possibilities curve, a point inside the curve represents', options: ['output the country cannot yet reach', 'unemployed or underused resources', 'full and efficient use of resources', 'economic growth over a period of time'], correctAnswer: 1, explanation: 'A point inside the PPC means the economy could produce more of both goods with its existing resources, so some are idle or misused. Points outside the curve are unattainable, points on the curve are efficient, and growth shows up as an outward shift of the whole curve.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'A PPC that is bowed outward from the origin reflects', options: ['constant opportunity costs between the goods', 'technology improving in one industry over time', 'unemployment of some resources in the economy', 'resources that are not equally suited to both goods'], correctAnswer: 3, explanation: 'A bowed-out PPC shows increasing opportunity cost: as more of one good is made, resources less suited to it must be shifted over, so each extra unit costs more of the other good. Equally suited resources produce a straight-line PPC, technology change shifts or pivots the curve, and unemployment puts the economy inside the curve.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'With constant opportunity costs, a farm can grow either 120 bushels of wheat or 40 bushels of corn on its land. What is the opportunity cost of 1 bushel of corn?', options: ['3 bushels of wheat', '0.33 bushels of wheat', '40 bushels of wheat', '80 bushels of wheat'], correctAnswer: 0, explanation: 'Giving up all 120 bushels of wheat yields 40 bushels of corn, so each bushel of corn costs 120 ÷ 40 = 3 bushels of wheat. One-third of a bushel is the cost of wheat measured in corn, and 40 and 80 confuse the totals with the per-unit trade-off.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'In one hour, Ana can bake 6 pies or 12 loaves of bread, while Ben can bake 4 pies or 4 loaves. Which statement about the two bakers is correct?', options: ['Comparative advantage in pies belongs to Ana', 'Comparative advantage in pies belongs to Ben', 'Comparative advantage in loaves belongs to Ben', 'Comparative advantage in both goods belongs to Ana'], correctAnswer: 1, explanation: 'A pie costs Ana 2 loaves but costs Ben only 1 loaf, so Ben has the lower opportunity cost and the comparative advantage in pies, leaving Ana with the advantage in loaves. Ana has the absolute advantage in both goods, but no one can hold the comparative advantage in both.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'In one hour, Ana can bake 6 pies or 12 loaves of bread, while Ben can bake 4 pies or 4 loaves. If they specialize and trade, which price for one pie would benefit both bakers?', options: ['0.5 loaves per pie', '2.5 loaves per pie', '1.5 loaves per pie', '3.0 loaves per pie'], correctAnswer: 2, explanation: 'Mutually beneficial terms of trade lie between the two opportunity costs of a pie: 1 loaf for Ben and 2 loaves for Ana. At 1.5 loaves, Ben earns more than his cost and Ana pays less than hers; a price of 0.5 is below Ben\'s cost, and 2.5 or 3.0 exceeds what Ana would pay.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  { question: 'In a market economy, the questions of what to produce and for whom are answered mainly by', options: ['central planners who set output targets', 'customs handed down across generations', 'elected officials who assign resources', 'prices set by buyers and sellers'], correctAnswer: 3, explanation: 'Market economies allocate resources through prices that arise from the decisions of buyers and sellers. Central planners describe a command economy, customs describe a traditional economy, and officials assigning resources is also a form of command allocation.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 1, part: 1 },
  { question: 'A town\'s 9th snowplow reduces accident costs by \\$95,000 a year and its 10th reduces them by \\$60,000. Each plow costs \\$80,000 a year to operate. The town now runs ten plows. Marginal analysis says it should', options: ['cut back to nine snowplows', 'keep all ten snowplows', 'add an eleventh snowplow', 'reduce to eight snowplows'], correctAnswer: 0, explanation: 'The 10th plow adds \\$60,000 of benefit for \\$80,000 of cost, so dropping it raises net benefit, while the 9th plow\'s \\$95,000 benefit exceeds its cost. Keeping or adding plows funds units with MC above MB, and cutting to eight drops a plow worth more than it costs.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-scarcity-marginal-analysis', formSet: 2, part: 1 },
  // ── Domain: basic-concepts · micro-supply-demand ───────────────────────────────
  { question: 'Which event causes a decrease in the quantity demanded of gasoline, rather than a decrease in the demand for gasoline?', options: ['Carmakers raise new-vehicle prices', 'Household incomes fall sharply this year', 'Gas stations raise pump prices', 'Bus fares drop across the region'], correctAnswer: 2, explanation: 'A change in the good\'s own price moves buyers along the existing demand curve, changing quantity demanded. Pricier cars (a complement), lower incomes (gasoline is a normal good), and cheaper buses (a substitute) are all determinants that shift the whole demand curve left.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'When household incomes rise, the demand for store-brand canned soup falls. Store-brand canned soup is', options: ['a normal good', 'an inferior good', 'a public good', 'a luxury good'], correctAnswer: 1, explanation: 'An inferior good is one whose demand falls as income rises, because buyers switch to preferred alternatives. A normal good, including a luxury, sees demand rise with income, and a public good is defined by being nonrival and nonexcludable, not by how demand responds to income.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'The price of butter rises sharply. In the market for margarine, a substitute for butter, we expect', options: ['demand to decrease, lowering price and quantity', 'demand to stay fixed as quantity demanded rises', 'supply to increase, lowering the price', 'demand to increase, raising price and quantity'], correctAnswer: 3, explanation: 'When a substitute becomes more expensive, buyers switch toward margarine, shifting its demand curve right and raising both equilibrium price and quantity. Demand falling is the complement result, the change is a shift rather than a movement along the curve, and butter\'s price does not affect margarine supply.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'Movie theaters raise ticket prices substantially. Assuming popcorn sold at theaters is a complement to movie tickets, what happens in the market for theater popcorn?', options: ['The price falls and quantity falls', 'The price rises and quantity falls', 'The price falls and quantity rises', 'The price rises and quantity rises'], correctAnswer: 0, explanation: 'Higher ticket prices mean fewer moviegoers, so demand for the complement shifts left, lowering both equilibrium price and quantity. A higher price with lower quantity describes a supply decrease, a lower price with higher quantity describes a supply increase, and rising price and quantity describe a demand increase.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'A new robotic system cuts the cost of assembling bicycles. In the market for bicycles,', options: ['the price rises and quantity falls', 'the price falls and quantity falls', 'the price falls and quantity rises', 'the price rises and quantity rises'], correctAnswer: 2, explanation: 'Lower production costs shift supply to the right, which lowers equilibrium price and raises equilibrium quantity. A higher price with lower quantity is a supply decrease, both falling is a demand decrease, and both rising is a demand increase.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'Shoppers come to expect that laptop prices will rise sharply next month. What happens in today\'s laptop market?', options: ['Demand rises, raising today\'s price and quantity', 'Demand falls, lowering today\'s price and quantity', 'Supply rises, lowering today\'s price and raising quantity', 'Quantity demanded falls along today\'s demand curve'], correctAnswer: 0, explanation: 'Expecting higher future prices leads buyers to purchase now, so today\'s demand shifts right, raising price and quantity. Falling demand is the response to expected price cuts, the expectation is about buyers rather than sellers, and a determinant shifts the curve instead of moving along it.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'At a price of \\$8, the quantity demanded of a good is 200 units and the quantity supplied is 350 units. Which statement describes this market?', options: ['There is a shortage of 150 units, so the price rises', 'There is a surplus of 150 units, so the price rises', 'There is a shortage of 350 units, so the price falls', 'There is a surplus of 150 units, so the price falls'], correctAnswer: 3, explanation: 'Quantity supplied exceeds quantity demanded by 350 − 200 = 150, a surplus, and sellers cut prices to clear unsold goods. A shortage would require quantity demanded to exceed quantity supplied, and a surplus pushes price down, not up.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'The market price of wheat rises. For an individual wheat farmer, this causes', options: ['a rightward shift of the entire supply curve', 'an increase in quantity supplied along the supply curve', 'a leftward shift of the entire supply curve', 'a decrease in quantity supplied along the supply curve'], correctAnswer: 1, explanation: 'A change in the good\'s own price moves the farmer along the existing supply curve, and the law of supply says a higher price brings a larger quantity supplied. Shifts of the supply curve come from determinants such as input costs or technology, and a decrease in quantity supplied would follow a price drop.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'Which pair of events would both shift the demand for electric cars to the right?', options: ['A rise in gasoline prices and a fall in electric-car prices', 'A fall in gasoline prices and a rise in buyers\' incomes', 'A rise in charging costs and a rise in buyers\' own incomes', 'A rise in gasoline prices and a fall in charging costs'], correctAnswer: 3, explanation: 'Pricier gasoline makes gas cars (a substitute) less attractive, and cheaper charging lowers the cost of a complement, so both increase demand. A fall in the electric car\'s own price changes quantity demanded, cheaper gasoline shifts demand left, and higher charging costs also shift it left.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'The law of supply states that, other things equal, a higher price leads to', options: ['a smaller quantity supplied', 'a rightward shift in supply', 'a larger quantity supplied', 'a larger quantity demanded'], correctAnswer: 2, explanation: 'The law of supply describes the positive relationship between a good\'s price and the quantity sellers offer, a movement along the supply curve. A smaller quantity is the opposite relationship, a shift comes from a non-price determinant, and a higher price reduces, not raises, quantity demanded.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'After a new licensing fee is introduced, several firms leave the market for craft beer. Demand is unchanged. In this market,', options: ['the price falls and quantity rises', 'the price rises and quantity falls', 'the price falls and quantity falls', 'the price rises and quantity rises'], correctAnswer: 1, explanation: 'Fewer sellers shift supply to the left, so equilibrium price rises and quantity falls. A lower price with higher quantity is a supply increase, both falling is a demand decrease, and both rising would need demand to increase.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'A recession lowers household incomes. Used cars are an inferior good and new cars are a normal good. Holding supply constant, what happens to prices in the two markets?', options: ['Used-car prices rise and new-car prices fall', 'Used-car prices fall and new-car prices rise', 'Used-car prices and new-car prices both rise', 'Used-car prices and new-car prices both fall'], correctAnswer: 0, explanation: 'Lower income increases demand for inferior goods and decreases demand for normal goods, so used-car demand shifts right and new-car demand shifts left. The reversed pattern treats the goods\' types backward, and both markets cannot move together because the goods respond to income in opposite directions.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'When the price of chicken rises, some shoppers switch to buying pork instead. This response is called', options: ['the income effect', 'a change in demand', 'a change in supply', 'the substitution effect'], correctAnswer: 3, explanation: 'The substitution effect is buyers turning to relatively cheaper alternatives when a good\'s price rises. The income effect is the drop in purchasing power from a higher price, and the switch is a movement along chicken\'s demand curve rather than a shift in its demand or supply.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'If a market\'s price is held below the equilibrium price, then', options: ['quantity supplied exceeds quantity demanded', 'quantity demanded exceeds quantity supplied', 'demand shifts left until the market clears', 'buyers and sellers want the same amount'], correctAnswer: 1, explanation: 'Below equilibrium, buyers want more than sellers offer, creating a shortage that puts upward pressure on price. Excess quantity supplied happens above equilibrium, the price itself does not shift demand, and quantities match only at equilibrium.', difficulty: 'easy', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  { question: 'A news story says, "Cheaper solar panels have led homeowners to buy more panels than ever." An economist would describe the effect of the lower price on buyers as', options: ['an increase in the demand for solar panels', 'an increase in the supply of solar panels', 'a rise in the quantity demanded of panels', 'a decrease in the demand for solar panels'], correctAnswer: 2, explanation: 'A lower price of the good itself moves buyers down along their demand curve, which is an increase in quantity demanded, not in demand. The price drop was likely caused by a supply increase, but that is the cause rather than the buyers\' response, and demand decreasing would mean fewer purchases at each price.', difficulty: 'hard', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 1, part: 1 },
  { question: 'A market schedule shows: at \\$4, quantity demanded is 90 and quantity supplied is 30; at \\$6, 70 and 50; at \\$8, 60 and 60; at \\$10, 40 and 80. The equilibrium price and quantity are', options: ['\\$8 and 60 units', '\\$6 and 70 units', '\\$10 and 80 units', '\\$4 and 90 units'], correctAnswer: 0, explanation: 'Equilibrium is the price at which quantity demanded equals quantity supplied, which happens at \\$8 with 60 units. At \\$6 and \\$4 there are shortages, and at \\$10 there is a surplus; the distractors pair each price with one side of the market only.', difficulty: 'medium', domain: 'basic-concepts', topicSlug: 'micro-supply-demand', formSet: 2, part: 1 },
  // ── Domain: supply-demand · micro-demand-supply-equilibrium ───────────────────
  { question: 'Priya would pay up to \\$45 for a concert ticket and buys one for \\$30. The seller would have accepted as little as \\$18. What is Priya\'s consumer surplus?', options: ['\\$12', '\\$27', '\\$30', '\\$15'], correctAnswer: 3, explanation: 'Consumer surplus is willingness to pay minus the price paid: \\$45 − \\$30 = \\$15. Twelve dollars is the seller\'s producer surplus, \\$27 is the total surplus from the trade, and \\$30 is simply the price.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'A buyer values a used bike at \\$200, the seller would accept any price of at least \\$120, and they agree on \\$150. What is the total surplus from this trade?', options: ['\\$50', '\\$30', '\\$80', '\\$150'], correctAnswer: 2, explanation: 'Total surplus is the buyer\'s value minus the seller\'s minimum, \\$200 − \\$120 = \\$80, no matter what price splits it. Fifty dollars is only the buyer\'s surplus, \\$30 is only the seller\'s, and \\$150 is the price.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'On a supply-and-demand graph, consumer surplus is the area', options: ['below demand and above the price', 'above supply and below the market price', 'the whole region under the demand curve', 'between the curves past equilibrium'], correctAnswer: 0, explanation: 'Consumer surplus is the gap between what buyers are willing to pay, shown by the demand curve, and the price they actually pay. The area above supply and below price is producer surplus, the whole area under demand is total value to buyers, and the region past equilibrium is where deadweight loss appears when output is too high.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'A heat wave raises the demand for electric fans at the same time a factory fire reduces the supply of fans. Which outcome is certain?', options: ['Quantity must rise, while price could go either way', 'Price must rise, while quantity could move either way', 'Quantity must fall, while price could go either way', 'Both price and quantity must rise in this market'], correctAnswer: 1, explanation: 'Higher demand and lower supply both push price up, so the price increase is certain. Demand pushes quantity up while supply pushes it down, so the quantity change depends on which shift is larger; claiming both rise ignores the supply decrease.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'Which combination of shifts will definitely raise the equilibrium quantity but has an uncertain effect on the equilibrium price?', options: ['Market demand rises and market supply rises', 'Market demand rises and market supply falls', 'Market demand falls and market supply rises', 'Market demand falls and market supply falls'], correctAnswer: 0, explanation: 'When demand and supply both increase, both push quantity up, while demand raises price and supply lowers it, leaving price uncertain. Rising demand with falling supply makes price certain, falling demand with rising supply makes price certain too, and both falling makes quantity definitely fall.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'In a competitive market with no externalities, why is the equilibrium quantity allocatively efficient?', options: ['Consumer surplus equals producer surplus at that quantity', 'Total revenue for sellers is at its highest possible level', 'Marginal benefit equals marginal cost for the last unit', 'Every buyer pays the lowest price that any seller accepts'], correctAnswer: 2, explanation: 'At equilibrium, the demand curve (marginal benefit) meets the supply curve (marginal cost), so every unit worth more than it costs is produced and none worth less. Consumer and producer surplus need not be equal, revenue maximization is a separate idea, and buyers pay the market price rather than each seller\'s minimum.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'A government order forces a competitive market to produce 20 percent more than its equilibrium quantity. For the extra units produced,', options: ['marginal benefit exceeds marginal cost, adding to total surplus', 'marginal cost exceeds marginal benefit, creating deadweight loss', 'consumer surplus rises enough to offset all producer losses', 'total surplus is unchanged, since price adjusts to clear it'], correctAnswer: 1, explanation: 'Beyond equilibrium, the supply curve lies above the demand curve, so each extra unit costs more to make than buyers value it, and total surplus shrinks by a deadweight loss. Marginal benefit exceeding marginal cost describes units below equilibrium, and no price change can make overproduced units worth their cost.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'A tax reduces the number of rideshare trips in a city from 1,000 to 800 a day. The deadweight loss of the tax represents', options: ['the revenue the government collects on the 800 trips', 'the surplus moved from riders to drivers on 800 trips', 'the higher fares paid by riders who keep taking trips', 'the value lost from the 200 trips that no longer occur'], correctAnswer: 3, explanation: 'Deadweight loss is the surplus from mutually beneficial trades that the tax prevents, here the 200 trips that disappear. Tax revenue and the higher fares paid on remaining trips are transfers, not losses to society, and the tax moves surplus to the government rather than from riders to drivers.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'Supply increases in a competitive market while demand stays the same. What happens to consumer surplus?', options: ['It falls, since sellers now earn a lower price', 'It grows, since buyers pay less and buy more', 'It falls, as the price and quantity both decrease', 'It is unchanged, as the demand curve did not shift'], correctAnswer: 1, explanation: 'A supply increase lowers price and raises quantity, so existing buyers pay less and new buyers enter, enlarging the area below demand and above price. Lower prices for sellers reduce producer surplus, not consumer surplus; quantity rises rather than falls; and consumer surplus changes whenever price does, even if demand is fixed.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'A binding price ceiling cuts the quantity traded in a market from 100 units to 60. At 60 units, buyers value the last unit at \\$14 and sellers\' marginal cost is \\$6. With linear curves, the deadweight loss is', options: ['\\$160', '\\$320', '\\$240', '\\$80'], correctAnswer: 0, explanation: 'Deadweight loss is the triangle between demand and supply over the lost units: ½ × (100 − 60) × (\\$14 − \\$6) = ½ × 40 × \\$8 = \\$160. Three hundred twenty dollars forgets the ½, \\$240 uses the 60 units still traded as the base, and \\$80 uses half the lost quantity as well as the ½.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'For a seller, producer surplus is the difference between', options: ['a buyer\'s highest price and the price paid', 'total revenue and the firm\'s total fixed cost', 'the market price and the average price in the market', 'the price received and the lowest price they would accept'], correctAnswer: 3, explanation: 'Producer surplus measures how much more a seller receives than the minimum needed to sell, which is the price minus the seller\'s cost shown on the supply curve. The gap between willingness to pay and price is consumer surplus, and fixed costs and average prices are not part of the definition.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'Demand for oat milk increases, and at the same time supply of oat milk increases by a much larger amount. What happens to the equilibrium?', options: ['The price rises and quantity also rises', 'The price falls and quantity is unchanged', 'The price falls and quantity rises', 'The price is unchanged and quantity rises'], correctAnswer: 2, explanation: 'Both shifts push quantity up, so quantity rises, and because the supply increase dominates, its downward pressure on price outweighs demand\'s upward pressure. A higher price would require the demand shift to dominate, quantity cannot stay put when both curves move right, and an unchanged price requires equal-sized shifts.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'A study finds that coffee has major health benefits just as a frost destroys much of Brazil\'s coffee crop. In the coffee market, buyers and sellers will see', options: ['a higher price and an uncertain quantity', 'a higher quantity and an uncertain price', 'a lower price and an uncertain quantity', 'a lower quantity and an uncertain price'], correctAnswer: 0, explanation: 'The health news raises demand and the frost reduces supply; both push price up, so price rises for sure. Demand pushes quantity up and supply pushes it down, so the quantity effect depends on which shift is larger, and neither shift points toward a lower price.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'Which situation creates deadweight loss in an otherwise competitive market?', options: ['Price settling at the equilibrium level', 'Demand increasing and raising the price', 'Supply and demand both shifting to the right', 'Output held below the equilibrium quantity'], correctAnswer: 3, explanation: 'Producing less than the equilibrium quantity means units with marginal benefit above marginal cost go unmade, which is deadweight loss. A market at equilibrium has none, and shifts in demand or supply simply move the market to a new efficient equilibrium.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  { question: 'A linear demand curve meets the vertical axis at \\$30 and crosses supply at a price of \\$10 and a quantity of 50. What is consumer surplus at equilibrium?', options: ['\\$250', '\\$750', '\\$500', '\\$1,500'], correctAnswer: 2, explanation: 'Consumer surplus is the triangle below demand and above price: ½ × 50 × (\\$30 − \\$10) = \\$500. Two hundred fifty dollars halves it twice, \\$750 uses the full \\$30 height, and \\$1,500 is the area of a rectangle with height \\$30.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 1, part: 1 },
  { question: 'Five buyers will each buy one unit if the price is at or below their willingness to pay: \\$9, \\$8, \\$6, \\$5, and \\$3. If the market price is \\$5, total consumer surplus is', options: ['\\$6', '\\$8', '\\$20', '\\$28'], correctAnswer: 1, explanation: 'The four buyers who purchase earn \\$4 + \\$3 + \\$1 + \\$0 = \\$8; the \\$3 buyer does not purchase, so that value is not subtracted. Six dollars wrongly counts the non-buyer as a negative, \\$20 is total spending, and \\$28 is the buyers\' total willingness to pay.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-demand-supply-equilibrium', formSet: 2, part: 1 },
  // ── Domain: supply-demand · micro-elasticity ──────────────────────────────────
  { question: 'A 10 percent increase in the price of concert tickets causes a 25 percent decrease in the quantity of tickets demanded. The price elasticity of demand is', options: ['0.4, so demand is inelastic', '2.5, so demand is inelastic', '2.5, so demand is elastic', '0.4, so demand is elastic'], correctAnswer: 2, explanation: 'Price elasticity is the percentage change in quantity divided by the percentage change in price, 25 ÷ 10 = 2.5, and a value above 1 means demand is elastic. The value 0.4 inverts the formula, and a coefficient of 2.5 cannot be inelastic.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'Which of the following most likely has the most price-elastic demand?', options: ['Insulin for diabetic patients', 'One brand of bottled water', 'Table salt for home cooking', 'Gasoline over the next week'], correctAnswer: 1, explanation: 'A single brand of bottled water has many close substitutes, so buyers switch easily when its price rises. Insulin is a necessity with no substitutes, salt takes a tiny share of the budget, and gasoline demand is very inelastic in the short run.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'A city raises bus fares from \\$2.00 to \\$2.50, and its total fare revenue falls. In this price range, demand for bus rides is', options: ['price inelastic', 'unit elastic', 'perfectly inelastic', 'price elastic'], correctAnswer: 3, explanation: 'If a price increase lowers total revenue, quantity must have fallen by a larger percentage than price rose, which is elastic demand. With inelastic demand revenue would rise, with unit elastic demand it would stay the same, and perfectly inelastic demand would leave quantity unchanged and raise revenue.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'A café cuts the price of a sandwich from \\$8 to \\$6, and daily sales rise from 100 to 120 sandwiches. Which statement is correct?', options: ['Revenue falls by \\$80, so demand is inelastic', 'Revenue rises by \\$80, so demand is elastic', 'Revenue falls by \\$80, so demand is elastic', 'Revenue rises by \\$120, so demand is inelastic'], correctAnswer: 0, explanation: 'Revenue drops from \\$800 to \\$720, a loss of \\$80, and a price cut that lowers revenue means demand is inelastic. The other options misstate the revenue change or pair a revenue decline after a price cut with elastic demand, which would raise revenue instead.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'When the price of printers rises 10 percent, the quantity of ink cartridges demanded falls 15 percent. The cross-price elasticity of demand and the relationship between the goods are', options: ['−1.5, so the goods are complements', '+1.5, so the goods are substitutes', '−0.67, so the goods are complements', '+0.67, so the goods are substitutes'], correctAnswer: 0, explanation: 'Cross-price elasticity is the percentage change in quantity of ink divided by the percentage change in printer prices, −15 ÷ 10 = −1.5, and a negative value means the goods are complements. A positive sign would indicate substitutes, and 0.67 inverts the ratio.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'When average income rises 8 percent, the quantity of streaming subscriptions demanded rises 12 percent. Streaming subscriptions are', options: ['a necessity with an income elasticity of 0.67', 'a luxury with an income elasticity of 1.5', 'an inferior good with an income elasticity of −1.5', 'a normal good with an income elasticity of 0.67'], correctAnswer: 1, explanation: 'Income elasticity is 12 ÷ 8 = 1.5; a positive value above 1 means a normal good that is income elastic, a luxury. A value of 0.67 inverts the formula, and a negative value would mean an inferior good, but demand rose with income.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'Along a straight-line, downward-sloping demand curve, how does total revenue change as the price is lowered from the top of the curve toward zero?', options: ['It rises the whole way, as quantity increases with each cut', 'It falls the whole way, as each price cut loses revenue', 'It rises until the unit-elastic midpoint, then falls after that point', 'It stays constant, as elasticity is the same at every point'], correctAnswer: 2, explanation: 'The upper part of a linear demand curve is elastic, so price cuts raise revenue, and the lower part is inelastic, so cuts reduce it; revenue peaks at the unit-elastic midpoint. Revenue cannot rise or fall throughout, and the slope is constant but elasticity is not.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'Two years after a sharp rise in gasoline prices, gasoline use has fallen far more than it did in the first month. This pattern shows that demand', options: ['becomes less elastic as buyers get used to the price', 'shifts right as buyers expect further price increases', 'becomes perfectly inelastic once prices stabilize again', 'becomes more elastic as buyers have time to adjust'], correctAnswer: 3, explanation: 'Over time buyers can switch to fuel-efficient cars, transit, or closer housing, so quantity responds more to the same price change. A smaller response would mean less elastic demand, expected price increases would raise purchases rather than lower them, and perfectly inelastic demand would show no response at all.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'A demand curve that is perfectly vertical has a price elasticity of', options: ['zero, perfectly inelastic', 'infinity, perfectly elastic', 'one, unit elastic', 'between zero and one'], correctAnswer: 0, explanation: 'A vertical demand curve means quantity demanded does not change at all when price changes, so elasticity is zero. A horizontal curve is perfectly elastic, unit elasticity means equal percentage changes, and values between zero and one describe ordinary inelastic demand.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'Demand for wheat is price inelastic. A record harvest greatly increases the supply of wheat. What happens to farmers\' total revenue?', options: ['It rises, as quantity rises more in percent than price drops', 'It rises, as farmers sell more bushels at the market price', 'It stays the same, as supply and demand both adjust', 'It falls, as price drops more in percentage terms than quantity rises'], correctAnswer: 3, explanation: 'With inelastic demand, a larger supply must push price down sharply to get buyers to take the extra wheat, so the percentage price drop exceeds the percentage quantity gain and revenue falls. A larger quantity response describes elastic demand, selling more bushels ignores the lower price, and demand does not shift here.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'A 5 percent increase in transit fares reduces ridership by 2 percent, while a 5 percent increase in parking fees reduces downtown parking by 9 percent. A city wants to raise more revenue from both. It should', options: ['lower transit fares and raise parking fees', 'raise both transit fares and parking fees', 'raise transit fares and lower parking fees', 'lower both transit fares and parking fees'], correctAnswer: 2, explanation: 'Transit demand is inelastic (2 ÷ 5 = 0.4), so higher fares raise revenue; parking demand is elastic (9 ÷ 5 = 1.8), so lower fees raise revenue. The other options apply the wrong direction to at least one market by ignoring which demand is elastic.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'The supply of original paintings by an artist who has died is', options: ['perfectly elastic', 'perfectly inelastic', 'unit elastic', 'relatively elastic'], correctAnswer: 1, explanation: 'No more original paintings can be produced at any price, so quantity supplied cannot respond and the supply curve is vertical. Perfectly elastic supply is horizontal, and unit or relatively elastic supply would require some ability to expand output.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'The price elasticity of supply for a good is generally greater when', options: ['the good has many close substitutes for buyers', 'the good is a large share of buyers\' budgets', 'producers have more time to adjust output', 'production requires rare inputs in fixed supply'], correctAnswer: 2, explanation: 'Supply becomes more elastic as firms gain time to hire workers, add capacity, or enter the market. Substitutes and budget share are determinants of demand elasticity, not supply elasticity, and inputs in fixed supply make supply less elastic.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'Two goods have a cross-price elasticity of demand of +0.8. The goods are', options: ['complements', 'substitutes', 'inferior goods', 'unrelated goods'], correctAnswer: 1, explanation: 'A positive cross-price elasticity means a higher price for one good raises the quantity demanded of the other, which defines substitutes. Complements have a negative cross-price elasticity, unrelated goods have one near zero, and inferior goods are defined by income elasticity.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  { question: 'Income rises 10 percent. The quantity demanded of Good A rises 4 percent, Good B rises 15 percent, and Good C falls 6 percent. Which classification is correct?', options: ['B is a luxury, A is a necessity, and C is inferior', 'A is a luxury, B is a necessity, and C is inferior', 'C is a luxury, A is a necessity, and B is inferior', 'B is a luxury, C is a necessity, and A is inferior'], correctAnswer: 0, explanation: 'Income elasticities are 0.4 for A, 1.5 for B, and −0.6 for C. A value above 1 marks a luxury, a value between 0 and 1 marks a necessity, and a negative value marks an inferior good, so B, A, and C fit those categories in that order.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 1, part: 1 },
  { question: 'Demand for table salt is very price inelastic, while demand for new cars is relatively elastic. The best explanation is that', options: ['salt has many more close substitutes than new cars', 'car buyers have less time to adjust to price changes', 'salt is a luxury good while new cars are necessities', 'salt takes a far smaller share of a household budget'], correctAnswer: 3, explanation: 'When a good costs a tiny share of income, even a large percentage price change barely affects buyers, so demand is inelastic. More substitutes would make salt more elastic, not less; car buyers typically can delay purchases; and salt is a necessity rather than a luxury.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-elasticity', formSet: 2, part: 1 },
  // ── Domain: supply-demand · micro-government-intervention ─────────────────────
  { question: 'A city caps apartment rents at \\$1,200 a month when the equilibrium rent is \\$1,500. The cap is', options: ['a binding ceiling that causes a surplus', 'a nonbinding ceiling with no effect', 'a binding ceiling that causes a shortage', 'a nonbinding ceiling that raises rents'], correctAnswer: 2, explanation: 'A ceiling below equilibrium is binding: at \\$1,200, more renters want apartments than landlords offer, so there is a shortage. A surplus comes from a binding floor, and a ceiling is nonbinding only when it is set above equilibrium.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'The government sets a minimum price of \\$3.00 per gallon of milk. The equilibrium price is \\$3.50. What does this price floor do?', options: ['It creates a surplus of milk', 'It creates a shortage of milk', 'It pushes the price down to \\$3.00', 'It has no effect on price or quantity'], correctAnswer: 3, explanation: 'A price floor only binds when it is set above equilibrium; at \\$3.00 it is below the \\$3.50 market price, so the market is unaffected. A surplus would need a floor above equilibrium, a shortage comes from a binding ceiling, and a floor never pushes price down.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'A binding price ceiling is set on a good. At the ceiling price, buyers want 900 units and sellers offer 500 units. How many units are actually bought and sold?', options: ['500 units', '900 units', '400 units', '700 units'], correctAnswer: 0, explanation: 'With a binding ceiling, the quantity traded is the smaller of quantity demanded and quantity supplied, because buyers cannot buy units sellers will not offer. Nine hundred is what buyers want, 400 is the size of the shortage, and 700 is a midpoint with no economic meaning.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'Demand for cigarettes is much less elastic than supply. A \\$1 per-pack excise tax is collected from sellers. Who bears most of the tax burden?', options: ['Sellers, since the tax is collected from them', 'Buyers, through a higher price', 'Buyers and sellers split it equally', 'The government, through lower sales'], correctAnswer: 1, explanation: 'The side of the market that is less elastic bears more of a tax, and here that is buyers, who pay a much higher price. Who sends the payment to the government does not change the economic incidence, an equal split happens only when elasticities are equal, and the government collects rather than bears the tax.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'Before a \\$4 per-unit tax, a good sold for \\$20. After the tax, buyers pay \\$23. How is the burden of the tax shared?', options: ['Buyers bear \\$3 and sellers bear \\$1', 'Buyers bear \\$4 and sellers bear \\$0', 'Buyers bear \\$1 and sellers bear \\$3', 'Buyers bear \\$3 and sellers bear \\$4'], correctAnswer: 0, explanation: 'Buyers pay \\$3 more than before, and sellers keep \\$23 − \\$4 = \\$19, which is \\$1 less than before. The shares must add up to the \\$4 tax, so the other splits either ignore the price change or exceed the tax.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'A \\$2 per-unit tax reduces the quantity sold in a market from 1,000 units to 800. With linear curves, what are the tax revenue and the deadweight loss?', options: ['Revenue of \\$2,000 and DWL of \\$200', 'Revenue of \\$1,600 and DWL of \\$400', 'Revenue of \\$2,000 and DWL of \\$0', 'Revenue of \\$1,600 and DWL of \\$200'], correctAnswer: 3, explanation: 'Revenue is the tax times the units still sold, \\$2 × 800 = \\$1,600, and deadweight loss is the triangle ½ × 200 × \\$2 = \\$200. Using the pre-tax 1,000 units overstates revenue, \\$400 omits the ½, and a tax that reduces quantity always creates some deadweight loss.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'Lawmakers debate whether to collect a new gasoline tax from drivers at the pump or from gas stations. Economic analysis predicts that', options: ['drivers bear more if they pay it directly', 'stations bear all of it if they pay it', 'the burden split is the same either way', 'whoever writes the check bears most of it'], correctAnswer: 2, explanation: 'Tax incidence depends on the relative elasticities of supply and demand, not on who legally remits the tax, so the split of the burden is identical. The other choices all assume the legal payer bears the burden, which is the trap this principle addresses.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'If supply of a good is perfectly elastic, a per-unit tax on the good is borne', options: ['entirely by sellers', 'entirely by buyers', 'equally by both sides', 'mainly by the sellers'], correctAnswer: 1, explanation: 'With a horizontal supply curve, sellers will not accept any price below their constant cost, so the market price rises by the full tax and buyers bear all of it. Sellers bear the tax when supply is the inelastic side, and an equal split requires equal elasticities.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'The government pays producers a per-unit subsidy on a good whose market has no externalities. Compared with the free market, the subsidy', options: ['brings quantity to the efficient level, removing deadweight loss', 'lowers quantity, because buyers face a higher price', 'raises quantity beyond the efficient level, creating deadweight loss', 'leaves quantity unchanged and raises only producer profit'], correctAnswer: 2, explanation: 'A subsidy shifts supply right, so output rises past the point where marginal benefit equals marginal cost and the extra units are worth less than they cost. Without an externality the free market was already efficient, buyers pay a lower price rather than a higher one, and quantity does change.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'A \\$2 per-unit subsidy to producers raises the quantity sold from 500 units to 600 units. How much does the subsidy cost the government?', options: ['\\$1,000', '\\$200', '\\$100', '\\$1,200'], correctAnswer: 3, explanation: 'Government spending equals the subsidy per unit times the units sold with the subsidy, \\$2 × 600 = \\$1,200. One thousand dollars uses the pre-subsidy quantity, \\$200 counts only the extra 100 units, and \\$100 is simply the change in quantity.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'The government sets a price floor for cheese above the equilibrium price. The result is', options: ['a surplus of cheese', 'a shortage of cheese', 'no change in the market', 'a rise in cheese demand'], correctAnswer: 0, explanation: 'At a price above equilibrium, cheesemakers offer more than buyers want, leaving unsold cheese. A shortage comes from a binding ceiling, a floor above equilibrium is binding so the market changes, and a price floor does not shift demand.', difficulty: 'easy', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'Which consequence of a binding rent-control law is consistent with the supply-and-demand model?', options: ['Vacancy rates rise as fewer renters seek units', 'Landlords cut maintenance and offer fewer units', 'Rents rise above the market level over time', 'More new apartments are built to meet demand'], correctAnswer: 1, explanation: 'A binding ceiling lowers the return to landlords, so they reduce the quantity and quality of apartments supplied. Vacancies fall rather than rise because there is a shortage, legal rents are held below the market level, and lower returns discourage new construction.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'A binding price ceiling is imposed in a competitive market. Compared with the free-market equilibrium, producer surplus', options: ['falls, and part of it shifts to consumers', 'rises, since producers sell more units', 'is unchanged, since only buyers are affected', 'disappears entirely into deadweight loss'], correctAnswer: 0, explanation: 'Sellers receive a lower price on fewer units, so producer surplus falls; some of the lost amount goes to consumers who still buy at the lower price, and the rest becomes deadweight loss. Producers sell fewer, not more, units; sellers are directly affected; and only part of the loss is deadweight.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'A small country that takes the world price as given imposes a tariff on imported steel. Compared with free trade,', options: ['domestic production falls and imports rise', 'domestic production rises and imports fall', 'domestic production and imports both rise', 'domestic production rises and imports rise'], correctAnswer: 1, explanation: 'The tariff raises the domestic price above the world price, so domestic producers expand output while consumers buy less, and imports fill a smaller gap. The other choices have imports or domestic production moving the wrong way after the price increase.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  { question: 'A country imposes an import quota on sugar. The most likely effect is that the quota', options: ['lowers the domestic price, helping domestic consumers', 'raises government tariff revenue on each unit imported', 'increases the quantity of sugar that consumers buy', 'raises the domestic price, helping domestic producers'], correctAnswer: 3, explanation: 'Limiting imports reduces the supply available domestically, which raises the price and benefits domestic producers at consumers\' expense. A lower price is the opposite effect, a quota collects no tariff revenue, and the higher price reduces the quantity consumers buy.', difficulty: 'medium', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 1, part: 1 },
  { question: 'In a competitive labor market, the equilibrium wage is \\$12 with 950 workers employed. A \\$15 minimum wage is set, at which firms hire 800 workers and 1,100 people want jobs. What happens?', options: ['Employment falls by 300 and 150 people are unemployed', 'Employment rises by 150 and 300 people are unemployed', 'Employment falls by 150 and 300 people are unemployed', 'Employment falls by 150 and no one is left unemployed'], correctAnswer: 2, explanation: 'Employment drops from 950 to the 800 that firms will hire, a fall of 150, and the surplus of labor is 1,100 − 800 = 300. The swapped numbers confuse the employment change with the surplus, a binding floor reduces rather than raises employment, and the excess job seekers are unemployed.', difficulty: 'hard', domain: 'supply-demand', topicSlug: 'micro-government-intervention', formSet: 2, part: 1 },
  // ── Domain: production-cost · micro-production-costs ────────────────────────────
  { question: 'A workshop\'s total output with 0, 1, 2, 3, and 4 workers is 0, 15, 35, 50, and 60 units, with capital fixed. What is the marginal product of the third worker?', options: ['50 units', '20 units', '15 units', '16.7 units'], correctAnswer: 2, explanation: 'Marginal product is the change in total output from adding the worker: 50 − 35 = 15 units. Fifty units is total product with three workers, 20 units is the second worker\'s marginal product, and 16.7 units is average product.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'A workshop\'s total output with 0, 1, 2, 3, and 4 workers is 0, 15, 35, 50, and 60 units, with capital fixed. Diminishing marginal returns begin with which worker?', options: ['The second worker', 'The fourth worker', 'The first worker', 'The third worker'], correctAnswer: 3, explanation: 'Marginal products are 15, 20, 15, and 10, so they rise through the second worker and first fall with the third. The second worker raised marginal product, and by the fourth worker diminishing returns were already under way.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'Which of the following is a fixed cost for a bakery in the short run?', options: ['Flour used in each batch of bread', 'The monthly lease on its storefront', 'Hourly wages of extra bakers', 'Electricity used to run ovens'], correctAnswer: 1, explanation: 'A lease payment must be made regardless of how much bread is baked, so it does not vary with output. Flour, hourly wages, and oven electricity all rise as the bakery produces more, making them variable costs.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'As a firm increases its output in the short run, average fixed cost', options: ['falls continuously', 'rises continuously', 'falls, then rises', 'stays constant'], correctAnswer: 0, explanation: 'Average fixed cost is fixed cost divided by output, so spreading the same fixed cost over more units makes it fall at every output level. It never rises, and the U shape of falling then rising belongs to AVC, ATC, and MC.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'At a firm\'s current output, marginal cost is \\$14 and average total cost is \\$10. If the firm produces one more unit, average total cost will', options: ['rise, since MC is above ATC', 'fall, since MC is above ATC', 'fall, since AFC keeps declining', 'stay the same, since ATC is at its minimum'], correctAnswer: 0, explanation: 'When the cost of the next unit exceeds the current average, adding it pulls the average up. MC above ATC cannot pull the average down, falling AFC is outweighed here by the high marginal cost, and ATC is at its minimum only where MC equals ATC.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'On a typical short-run cost graph, the marginal cost curve crosses the AVC and ATC curves', options: ['at their maximum points', 'at their minimum points', 'where each starts to fall', 'only where output is zero'], correctAnswer: 1, explanation: 'Whenever MC is below an average it pulls the average down, and when MC is above it pulls the average up, so MC must cross each average at its lowest point. AVC and ATC are U-shaped, so they have no maximum where MC crosses, and the crossing occurs at positive output.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'A firm has fixed cost of \\$100. Its total cost is \\$400 at 10 units of output and \\$425 at 11 units. What is its average variable cost at 10 units?', options: ['\\$40', '\\$10', '\\$25', '\\$30'], correctAnswer: 3, explanation: 'Variable cost at 10 units is total cost minus fixed cost, \\$400 − \\$100 = \\$300, so AVC is \\$300 ÷ 10 = \\$30. Forty dollars is ATC, \\$10 is AFC, and \\$25 is the marginal cost of the 11th unit.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'A firm has fixed cost of \\$100. Its total cost is \\$400 at 10 units of output and \\$425 at 11 units. What is the marginal cost of the 11th unit?', options: ['\\$425', '\\$38.64', '\\$25', '\\$325'], correctAnswer: 2, explanation: 'Marginal cost is the change in total cost, \\$425 − \\$400 = \\$25. Four hundred twenty-five dollars is total cost, \\$38.64 is ATC at 11 units, and \\$325 is variable cost at 11 units.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'When marginal product is below average product, average product is', options: ['rising', 'at its maximum', 'falling', 'equal to zero'], correctAnswer: 2, explanation: 'Adding a worker who produces less than the current average pulls the average down. Average product rises only when marginal product is above it, it peaks where the two are equal, and it stays positive as long as total output does.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'In economics, the long run is a period in which', options: ['every input is variable', 'at least one input is fixed', 'output cannot be changed', 'diminishing returns are strongest'], correctAnswer: 0, explanation: 'The long run is long enough for a firm to change every input, including plant size. The short run is defined by at least one fixed input, output can change in both periods, and diminishing marginal returns are a short-run idea because they require a fixed input.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'Which of the following is most likely to give a manufacturer economies of scale as it expands?', options: ['Managers struggling to coordinate a huge workforce', 'Adding workers to a fixed number of machines', 'Paying higher wages as the firm hires more people', 'Workers specializing in narrow tasks at a large plant'], correctAnswer: 3, explanation: 'Specialization at a larger scale raises productivity and lowers long-run average cost. Coordination problems cause diseconomies of scale, adding workers to fixed machines describes short-run diminishing returns, and rising wages would raise rather than lower average cost.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'A firm doubles every one of its inputs, and its output rises by only 60 percent. The firm is experiencing', options: ['economies of scale', 'diseconomies of scale', 'constant returns to scale', 'diminishing marginal returns'], correctAnswer: 1, explanation: 'When all inputs change and output grows proportionally less, long-run average cost rises, which is diseconomies of scale. Economies of scale would mean output more than doubles, constant returns would mean it exactly doubles, and diminishing marginal returns applies when only some inputs change.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'A restaurant with a fixed-size kitchen keeps hiring cooks, and each new cook adds fewer meals per hour than the cook hired before. This is best explained by', options: ['long-run diseconomies of scale', 'scale economies from specialization', 'rising average fixed cost per meal', 'diminishing marginal returns to labor'], correctAnswer: 3, explanation: 'Adding a variable input to a fixed kitchen eventually crowds workers, so each cook adds less output, which is diminishing marginal returns. Diseconomies of scale require changing all inputs in the long run, specialization would raise output per cook, and average fixed cost falls as output rises.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'In an industry where long-run average cost reaches its minimum at an output that is tiny relative to market demand, we would expect', options: ['one firm serving the whole market', 'a few very large firms', 'many fairly small firms', 'firms that keep growing larger'], correctAnswer: 2, explanation: 'If firms reach the lowest possible average cost at a small size, many firms can operate efficiently and the market supports a competitive structure. One firm or a few large firms is typical when minimum efficient scale is large relative to demand, and growing beyond minimum efficient scale brings no cost advantage.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'On a firm\'s short-run cost graph, the vertical distance between the ATC curve and the AVC curve', options: ['is average fixed cost, shrinking as output rises', 'is marginal cost, rising as output rises', 'is total fixed cost, constant at every output', 'is profit per unit, falling as output rises'], correctAnswer: 0, explanation: 'Because ATC = AVC + AFC, the gap between the two curves is AFC, which shrinks as fixed cost is spread over more units, so the curves get closer together. Marginal cost is a separate curve, total fixed cost is a total rather than a per-unit amount, and profit depends on price, which is not on a cost graph.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  { question: 'A firm\'s fixed cost is \\$500 and its variable cost of producing 40 units is \\$700. What is its average total cost at 40 units?', options: ['\\$17.50', '\\$30', '\\$12.50', '\\$1,200'], correctAnswer: 1, explanation: 'Average total cost is total cost divided by output: (\\$500 + \\$700) ÷ 40 = \\$30. Seventeen fifty is AVC, \\$12.50 is AFC, and \\$1,200 is total cost before dividing by quantity.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 2, part: 1 },
  { question: 'When a firm raises its output from 20 to 25 units, its variable cost rises from \\$300 to \\$400, and its fixed cost stays at \\$150. What is the marginal cost per unit over this range?', options: ['\\$100', '\\$20', '\\$16', '\\$22'], correctAnswer: 1, explanation: 'Marginal cost is the change in total cost divided by the change in output: \\$100 ÷ 5 = \\$20 per unit; fixed cost does not change, so it does not affect MC. One hundred dollars is the total change, \\$16 is AVC at 25 units, and \\$22 is ATC at 25 units.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-production-costs', formSet: 1, part: 1 },
  // ── Domain: production-cost · micro-perfect-competition ─────────────────────────
  { question: 'A wheat farmer in a perfectly competitive market cannot sell above the market price because', options: ['buyers can get identical wheat from many others', 'the government sets the market price of wheat', 'her marginal cost would exceed her revenue', 'demand for wheat is perfectly inelastic'], correctAnswer: 0, explanation: 'With many sellers offering identical products, any farmer who charges more than the market price loses all her customers, so she is a price taker. Prices are not set by the government in this model, her costs do not restrict her price, and the individual firm\'s demand is perfectly elastic, not inelastic.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'A perfectly competitive firm sells strawberries at a market price of \\$4 per box. What is its marginal revenue from the 50th box?', options: ['\\$200', '\\$0.08', '\\$4', '\\$2'], correctAnswer: 2, explanation: 'A price taker can sell every additional unit at the market price, so marginal revenue equals price, \\$4. Two hundred dollars is total revenue from 50 boxes, \\$0.08 divides price by quantity, and \\$2 wrongly applies the monopoly rule that MR falls below price.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'The market price is \\$12. A competitive firm\'s marginal cost is \\$9 for the 5th unit, \\$11 for the 6th, \\$13 for the 7th, and \\$16 for the 8th. How many units should it produce to maximize profit?', options: ['7 units', '5 units', '8 units', '6 units'], correctAnswer: 3, explanation: 'The firm should produce every unit whose marginal cost is at or below the \\$12 price, which includes the 6th unit (\\$11) but not the 7th (\\$13). Stopping at 5 gives up a profitable unit, while the 7th and 8th units cost more than the price they bring in.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'At its profit-maximizing output of 200 units, a competitive firm faces a price of \\$15 and an average total cost of \\$12. The firm earns', options: ['\\$600 in economic loss', '\\$600 in economic profit', '\\$3,000 in economic profit', '\\$2,400 in economic profit'], correctAnswer: 1, explanation: 'Profit is (P − ATC) × Q = (\\$15 − \\$12) × 200 = \\$600, and because price exceeds ATC it is a profit, not a loss. Three thousand dollars is total revenue, and \\$2,400 is total cost.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'At the output where MR = MC, a competitive firm has a price of \\$20, average total cost of \\$24, and average variable cost of \\$18. In the short run the firm should', options: ['shut down, as price is below ATC', 'operate, as the firm earns a profit', 'operate at a loss, as price covers AVC', 'exit now, as revenue is below cost'], correctAnswer: 2, explanation: 'Because price exceeds AVC, each unit covers its variable cost and contributes \\$2 toward fixed costs, so producing loses less than shutting down. Price below ATC alone does not justify shutting down, the firm is earning a loss rather than a profit, and exit is a long-run decision.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'A competitive firm\'s minimum AVC is \\$6 and its minimum ATC is \\$9. In the short run, the firm will shut down if the market price falls below', options: ['\\$9', '\\$7.50', '\\$3', '\\$6'], correctAnswer: 3, explanation: 'The shutdown rule compares price with average variable cost: below minimum AVC, the firm loses less by producing nothing. Nine dollars is the break-even price, below which the firm earns losses but still operates, while \\$7.50 and \\$3 have no special role.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'A perfectly competitive firm\'s short-run supply curve is', options: ['the MC curve above minimum AVC', 'the MC curve above minimum ATC', 'the MC curve below minimum AVC', 'the horizontal MR curve at the price'], correctAnswer: 0, explanation: 'The firm produces where P = MC as long as price covers AVC, so the part of MC above minimum AVC traces out its supply. Between minimum AVC and minimum ATC the firm still produces at a loss, below minimum AVC it shuts down, and the MR line shows price rather than quantity supplied.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'Firms in a perfectly competitive industry are currently earning economic profits. In the long run,', options: ['exit raises the price until all profit is zero', 'entry lowers the price until profit is zero', 'profits persist due to the barriers to entry', 'the price rises as more firms join the market'], correctAnswer: 1, explanation: 'Profits attract new firms, shifting market supply right and lowering price until it equals minimum ATC. Exit happens when firms suffer losses, perfect competition has no barriers to entry, and entry lowers rather than raises the price.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'A constant-cost competitive industry is in long-run equilibrium when demand for its product permanently increases. After all long-run adjustments,', options: ['price stays higher and industry output is higher', 'industry output is unchanged and price is back where it began', 'price falls below its original level as new firms enter', 'price returns to its original level and industry output is higher'], correctAnswer: 3, explanation: 'In a constant-cost industry, entry continues until price falls back to minimum ATC, which has not changed, so the long-run supply curve is horizontal and output expands. A higher long-run price describes an increasing-cost industry, output must rise to meet the higher demand, and entry stops once price reaches minimum ATC.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'In long-run equilibrium, a perfectly competitive industry achieves', options: ['allocative efficiency but not productive', 'productive efficiency but not allocative', 'allocative and productive efficiency', 'neither allocative nor productive efficiency'], correctAnswer: 2, explanation: 'In the long run, P = MC, which is allocative efficiency, and P = minimum ATC, which is productive efficiency. The other choices describe imperfect competition, where price exceeds marginal cost or output falls short of minimum ATC.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'A competitive firm\'s graph shows price at \\$10, MC = MR at 50 units, and ATC of \\$8 at 50 units. The profit rectangle on the graph has', options: ['a height of \\$2 and a width of 50, for \\$100', 'a height of \\$10 and a width of 50, for \\$500', 'a height of \\$8 and a width of 50, for \\$400', 'a height of \\$2 and a width of 10, for \\$20'], correctAnswer: 0, explanation: 'Profit per unit is P − ATC = \\$2, and multiplying by the 50 units sold gives \\$100. A height of \\$10 measures total revenue, \\$8 measures total cost, and the width must be the quantity produced, not the price.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'In an increasing-cost competitive industry, the long-run industry supply curve is', options: ['upward sloping', 'horizontal', 'downward sloping', 'vertical'], correctAnswer: 0, explanation: 'As firms enter, they bid up input prices, so each expansion of output happens at a higher minimum ATC and long-run supply slopes upward. A horizontal curve describes a constant-cost industry, a downward slope a decreasing-cost industry, and a vertical curve would mean output could never expand.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'A perfectly competitive industry starts in long-run equilibrium. Then market demand falls. In the short run, the typical firm', options: ['produces more to make up for the lower price', 'produces the same amount at the lower price', 'cuts output but still earns a normal profit', 'produces less and incurs an economic loss'], correctAnswer: 3, explanation: 'The lower price shifts the firm\'s MR line down, so it moves down its MC curve to a smaller output, and price now falls below ATC. Producing more or the same would ignore the P = MC rule, and since price started at minimum ATC, any drop means a loss.', difficulty: 'hard', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'A perfectly competitive firm is producing at an output where marginal revenue exceeds marginal cost. To raise its profit, the firm should', options: ['decrease output', 'raise its price', 'increase output', 'keep output unchanged'], correctAnswer: 2, explanation: 'When MR > MC, the next unit adds more to revenue than to cost, so producing more raises profit until MR = MC. Cutting output gives up profitable units, a price taker cannot raise its price, and staying put leaves profit unclaimed.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  { question: 'If a perfectly competitive firm shuts down in the short run, its economic loss equals', options: ['zero dollars', 'its total fixed cost', 'its total variable cost', 'its total cost'], correctAnswer: 1, explanation: 'A shut-down firm pays no variable costs but must still pay fixed costs such as rent, so its loss equals total fixed cost. The loss is not zero because fixed costs remain, variable costs disappear when output is zero, and total cost includes the variable costs it no longer pays.', difficulty: 'medium', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 1, part: 1 },
  { question: 'Which feature of perfect competition drives economic profit to zero in the long run?', options: ['Free entry and exit of firms', 'Identical products across sellers', 'Perfect information about prices', 'Many buyers in the same market'], correctAnswer: 0, explanation: 'Because firms can enter when there are profits and leave when there are losses, the market price is pushed to minimum ATC. Identical products and perfect information make firms price takers, and many buyers prevent any one buyer from setting the price, but none of these alone eliminates profit.', difficulty: 'easy', domain: 'production-cost', topicSlug: 'micro-perfect-competition', formSet: 2, part: 1 },
  // ── Domain: imperfect-competition · micro-monopoly ────────────────────────────────────
  { question: 'Which of the following is the best example of a natural monopoly?', options: ['A drug maker protected by a 20-year patent', 'A diamond firm that owns most of the mines', 'A city water system with huge fixed pipe costs', 'A popular restaurant run by a famous chef'], correctAnswer: 2, explanation: 'A natural monopoly arises when economies of scale are so large that one firm can supply the whole market at a lower average cost than several firms could, as with water pipes. A patent is a legal barrier, owning the mines is control of a key resource, and a restaurant faces many rivals.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'Why is a single-price monopolist\'s marginal revenue less than its price?', options: ['Its marginal cost rises as it produces more units', 'The government caps the price it is allowed to charge', 'Its demand curve is perfectly elastic at the market price', 'To sell more, it must lower the price on all units'], correctAnswer: 3, explanation: 'Because the monopolist faces the downward-sloping market demand curve, selling one more unit requires cutting the price on every unit sold, so the extra revenue is less than the price. Rising marginal cost affects costs, not revenue; no price cap is involved; and a perfectly elastic demand curve would make MR equal price.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'A monopolist can sell 4 units at \\$20 each or 5 units at \\$18 each. What is the marginal revenue of the 5th unit?', options: ['\\$18', '\\$10', '\\$90', '\\$2'], correctAnswer: 1, explanation: 'Total revenue rises from 4 × \\$20 = \\$80 to 5 × \\$18 = \\$90, so marginal revenue is \\$10. Eighteen dollars is the new price, \\$90 is total revenue, and \\$2 is only the price cut.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'A monopolist\'s MR equals its MC at 300 units. At 300 units, the demand curve shows a price of \\$40, MR is \\$20, and ATC is \\$30. What price does it charge, and what is its profit?', options: ['A price of \\$20 and a loss of \\$3,000', 'A price of \\$40 and profit of \\$3,000', 'A price of \\$40 and profit of \\$6,000', 'A price of \\$30 and profit of \\$0'], correctAnswer: 1, explanation: 'The monopolist charges the highest price buyers will pay for 300 units, read from the demand curve, and earns (\\$40 − \\$30) × 300 = \\$3,000. Using MR as the price confuses the two curves, \\$6,000 subtracts MR instead of ATC, and a \\$30 price is simply average total cost.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'Compared with a perfectly competitive industry with the same costs, an unregulated monopoly', options: ['charges a higher price and sells a smaller quantity', 'charges a higher price and sells a larger quantity', 'charges a lower price and sells a smaller quantity', 'charges the same price but earns more profit'], correctAnswer: 0, explanation: 'The monopolist restricts output to where MR = MC, which is below the competitive output where demand meets MC, and then charges the higher price on the demand curve. It cannot sell more at a higher price on the same demand curve, and its price is higher, not lower or equal.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'A profit-maximizing monopolist with positive marginal cost always produces on', options: ['the inelastic part of its demand curve', 'the unit-elastic point of its demand curve', 'the elastic part of its demand curve', 'the vertical part of its demand curve'], correctAnswer: 2, explanation: 'Profit maximization requires MR = MC, and with MC above zero, MR must be positive, which happens only where demand is elastic. In the inelastic range MR is negative, at the unit-elastic point MR is zero, and a vertical, perfectly inelastic section would also mean negative MR.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'A monopoly can keep earning economic profit in the long run because', options: ['its demand curve is perfectly elastic', 'it produces at the minimum of its ATC', 'it sets price equal to marginal cost', 'barriers to entry keep rivals out'], correctAnswer: 3, explanation: 'Barriers such as patents, control of resources, or economies of scale stop new firms from entering and competing profits away. A monopolist faces downward-sloping demand, usually does not produce at minimum ATC, and sets price above marginal cost.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'A monopoly is allocatively inefficient because, at its chosen output,', options: ['price equals average total cost', 'marginal revenue exceeds marginal cost', 'price is greater than marginal cost', 'price is below average variable cost'], correctAnswer: 2, explanation: 'Allocative efficiency requires price, which reflects marginal benefit, to equal marginal cost; a monopolist charges more than MC, so units that buyers value above their cost go unproduced. Price equal to ATC describes zero profit, a profit maximizer sets MR equal to MC, and price below AVC would mean shutting down.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'A regulator requires a natural monopoly to charge a price equal to its marginal cost. The firm will', options: ['earn a profit because price exceeds ATC', 'break even because price equals ATC', 'reduce output below the unregulated level', 'suffer a loss because MC is below ATC'], correctAnswer: 3, explanation: 'For a natural monopoly, ATC is still falling at market demand, so MC lies below ATC and a price set at MC cannot cover average cost; the firm needs a subsidy to stay open. Price equal to ATC describes fair-return pricing, and setting price at MC raises output above the unregulated level.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'Under fair-return pricing, a regulated natural monopoly charges the price at which', options: ['price equals marginal cost', 'price equals average total cost', 'marginal revenue equals marginal cost', 'price equals average variable cost'], correctAnswer: 1, explanation: 'Fair-return pricing sets price at ATC, so the firm earns zero economic profit while producing more than an unregulated monopoly would. Price equal to MC is the socially optimal rule, MR = MC is the unregulated profit-maximizing rule, and price at AVC would not cover fixed costs.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'A movie theater charges students \\$8 and other adults \\$14 for the same show. For this pricing strategy to work, the theater must', options: ['be able to prevent resale of the cheap tickets', 'face perfectly elastic demand from all its customers', 'charge each group a price equal to marginal cost', 'find the same demand elasticity in both groups'], correctAnswer: 0, explanation: 'Price discrimination requires market power, groups with different demand elasticities, and a way to prevent resale; otherwise students would buy cheap tickets and resell them to other adults. Perfectly elastic demand means no market power, pricing at MC leaves no gain, and identical elasticities would give no reason to charge different prices.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'Compared with a single-price monopolist facing the same demand and costs, a perfectly price-discriminating monopolist', options: ['produces less output and creates more deadweight loss', 'produces the efficient output and leaves no consumer surplus', 'keeps the same output and charges higher prices', 'produces more output and raises consumer surplus'], correctAnswer: 1, explanation: 'Charging each buyer exactly their willingness to pay makes the demand curve the marginal revenue curve, so the firm produces until price equals MC, eliminating deadweight loss but capturing all surplus as profit. It produces more, not less or the same, and consumers are left with no surplus.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'A monopolist\'s linear demand curve meets the price axis at \\$100 and the quantity axis at 50 units. At what quantity does its marginal revenue equal zero?', options: ['50 units', '100 units', '25 units', '12.5 units'], correctAnswer: 2, explanation: 'For a linear demand curve, the MR curve has the same price intercept and twice the slope, so it reaches zero at half the demand curve\'s quantity intercept, 25 units. Fifty units is where price is zero, 100 is the price intercept, and 12.5 halves the quantity twice.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'A monopolist\'s total revenue is at its maximum at the output where', options: ['marginal revenue equals zero', 'marginal revenue equals marginal cost', 'marginal revenue equals the price', 'price equals average total cost'], correctAnswer: 0, explanation: 'Total revenue rises while MR is positive and falls once MR turns negative, so it peaks where MR = 0, the unit-elastic point. MR = MC maximizes profit, not revenue; MR equals price only for a price taker, never for a monopolist selling more than one unit; and price equal to ATC is the zero-profit output.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  { question: 'At its current output, a monopolist\'s marginal revenue is \\$15 and its marginal cost is \\$9. To raise its profit, the firm should', options: ['decrease output and charge a higher price', 'keep output fixed and raise its price', 'expand output while keeping price the same', 'increase output and lower its price'], correctAnswer: 3, explanation: 'Since MR exceeds MC, producing more adds to profit, and to sell more the monopolist must move down its demand curve to a lower price. Cutting output gives up profitable units, raising price at the same output is impossible on the same demand curve, and a monopolist cannot sell more without lowering price.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 1, part: 1 },
  { question: 'A competitive industry is taken over by a single firm with the same costs, which then sets the monopoly price. What happens to consumer surplus?', options: ['It rises, as the monopoly can produce at lower cost', 'It falls, partly becoming profit and partly deadweight loss', 'It is unchanged, as market demand has not shifted', 'It falls, with all of it turning into deadweight loss'], correctAnswer: 1, explanation: 'The higher price shrinks consumer surplus: the area on units still sold becomes monopoly profit, and the area on units no longer sold becomes deadweight loss. Costs are assumed the same, consumer surplus depends on price and not only on demand, and part of the lost surplus goes to the firm.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopoly', formSet: 2, part: 1 },
  // ── Domain: imperfect-competition · micro-monopolistic-oligopoly ──────────────────────
  { question: 'Which market is the best example of monopolistic competition?', options: ['Hair salons in a large city', 'Wheat farms in the Midwest', 'Commercial jet manufacturers', 'The only power company in a town'], correctAnswer: 0, explanation: 'Hair salons are many firms selling differentiated services with easy entry, the defining traits of monopolistic competition. Wheat farms sell identical products in perfect competition, jet makers are a few firms in an oligopoly, and a sole power company is a monopoly.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'In long-run equilibrium, a firm in monopolistic competition earns zero economic profit because', options: ['the government regulates its prices', 'it produces at minimum average total cost', 'rivals enter as long as entry pays', 'its demand curve is perfectly elastic'], correctAnswer: 2, explanation: 'Low entry barriers let new firms with similar products appear whenever profits exist, taking customers until price equals ATC. Government regulation plays no role, the firm produces short of minimum ATC, and its demand curve slopes downward because its product is differentiated.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'A coffee shop in monopolistic competition earns economic profit. As similar shops open nearby, the first shop\'s demand curve', options: ['shifts right and becomes less elastic', 'becomes perfectly elastic at the market price', 'stays put while its costs rise to meet price', 'shifts left and becomes more elastic'], correctAnswer: 3, explanation: 'New rivals draw customers away, so the shop sells less at every price, and having more close substitutes makes its buyers more price-sensitive. Its demand does not grow, it remains downward sloping because its product is still differentiated, and entry works through demand rather than costs.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'In long-run equilibrium, a firm in monopolistic competition produces', options: ['exactly the output that minimizes ATC', 'more than the output that minimizes ATC', 'where price equals its marginal cost', 'less than the output that minimizes ATC'], correctAnswer: 3, explanation: 'The downward-sloping demand curve is tangent to ATC on its falling portion, to the left of minimum ATC, so the firm has excess capacity. Producing at minimum ATC is the perfectly competitive outcome, producing more would put it on the rising part of ATC, and its price exceeds marginal cost.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'On the long-run equilibrium graph for a firm in monopolistic competition, the demand curve is', options: ['touching ATC at its minimum point', 'above the ATC curve at the chosen output', 'tangent to the ATC curve at the chosen output', 'horizontal at the minimum of ATC'], correctAnswer: 2, explanation: 'Zero economic profit means price equals ATC at the profit-maximizing output, so the demand curve just touches ATC there, on ATC\'s downward-sloping section. Touching at the minimum describes perfect competition, demand above ATC would mean profits, and a horizontal demand curve belongs to a price taker.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'Compared with a perfectly competitive firm in long-run equilibrium, a monopolistically competitive firm in long-run equilibrium', options: ['has positive profit and P equal to MC', 'has the same zero profit but P above MC', 'has zero profit and P equal to MC', 'has positive profit and P above MC'], correctAnswer: 1, explanation: 'Free entry drives both structures to zero economic profit, but the monopolistically competitive firm faces downward-sloping demand, so its price exceeds marginal cost. Positive long-run profit is ruled out by entry, and price equal to MC holds only in perfect competition.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'What feature most distinguishes oligopoly from the other market structures?', options: ['Firms\' choices depend on rivals\' reactions', 'Firms sell identical goods at one price', 'Firms can freely enter and leave the market', 'One firm supplies the entire market alone'], correctAnswer: 0, explanation: 'With only a few large firms, each must consider how rivals will respond to its price or output decisions, which is strategic interdependence. Identical goods and free entry describe perfect competition, and a single seller is a monopoly.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'Two firms each choose to Advertise or Not. Payoffs in millions (A, B): both advertise (4, 4); only A advertises (9, 2); only B advertises (2, 9); neither advertises (6, 6). What is Firm A\'s dominant strategy?', options: ['Not advertise, whatever B does', 'Advertise only if B advertises', 'A has no dominant strategy here', 'Advertise, whatever B does'], correctAnswer: 3, explanation: 'If B advertises, A earns 4 by advertising versus 2 by not; if B does not, A earns 9 versus 6. Advertising is better in both cases, so it is dominant. Not advertising is never A\'s best response, and the choice does not depend on B\'s move.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'Two firms each choose to Advertise or Not. Payoffs in millions (A, B): both advertise (4, 4); only A advertises (9, 2); only B advertises (2, 9); neither advertises (6, 6). What is the Nash equilibrium of this game?', options: ['A and B both do not advertise, earning 6 each', 'A advertises and B does not, earning 9 and 2', 'A and B both advertise, earning 4 each', 'B advertises and A does not, earning 2 and 9'], correctAnswer: 2, explanation: 'Advertising is a dominant strategy for both firms, so each advertises and neither can gain by changing alone. Both staying quiet would pay more, but each firm would gain by switching to advertising, so that outcome is not stable, and the one-sided outcomes give the non-advertiser a reason to start advertising.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'The members of a cartel agree to restrict output to keep the price high. Each member has an incentive to cheat because', options: ['the cartel price is below each firm\'s marginal cost', 'it profits by selling extra units at the high cartel price', 'its rivals are required by law to match its price', 'cheating lowers its marginal revenue to zero'], correctAnswer: 1, explanation: 'At the high cartel price, each firm\'s price exceeds its marginal cost, so producing more than its quota adds to its own profit, even though it lowers joint profit if everyone cheats. The cartel price is above MC, no law forces matching prices, and cheating does not drive MR to zero.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'In a pricing game, Firm X\'s best response is High when Firm Y chooses High, and Low when Firm Y chooses Low. Firm X', options: ['has no dominant strategy', 'has a dominant strategy of High', 'has a dominant strategy of Low', 'is in Nash equilibrium at every outcome'], correctAnswer: 0, explanation: 'A dominant strategy is best regardless of the rival\'s choice, but X\'s best choice changes with Y\'s, so X has none. High and Low each lose their advantage when Y switches, and a Nash equilibrium requires both firms to be playing best responses, which is not true of every outcome.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'In a game, payoffs (A, B) are: A Up and B Left (5, 3); A Up and B Right (2, 4); A Down and B Left (4, 6); A Down and B Right (1, 2). What is the Nash equilibrium?', options: ['A chooses Up and B chooses Right', 'A chooses Up and B chooses Left', 'A chooses Down and B chooses Left', 'A chooses Down and B chooses Right'], correctAnswer: 0, explanation: 'Up is dominant for A (5 > 4 and 2 > 1), and given Up, B does better with Right (4 > 3), so neither firm can gain by switching alone. At Up and Left, B would switch to Right; at Down and Left, A would switch to Up; and at Down and Right, both would switch.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'If the firms in an oligopoly collude successfully, the market outcome most closely resembles', options: ['a perfectly competitive market', 'a single-firm monopoly', 'a monopolistically competitive market', 'a price war among rival firms'], correctAnswer: 1, explanation: 'Colluding firms act together to restrict output and raise price to the level a single monopolist would choose. Perfect and monopolistic competition involve many independent sellers, and a price war is what happens when collusion breaks down.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'Why do firms in monopolistic competition spend heavily on advertising and branding?', options: ['To make their products identical to rivals\'', 'To lower their marginal cost of production', 'To make demand for their product less elastic', 'To guarantee long-run economic profit'], correctAnswer: 2, explanation: 'Building brand loyalty makes buyers less willing to switch when price rises, giving the firm more pricing power. Firms differentiate rather than imitate, advertising raises rather than lowers costs, and entry still pushes long-run profit toward zero.', difficulty: 'easy', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  { question: 'Two firms each choose to Advertise or Not. Payoffs in millions (A, B): both advertise (4, 4); only A advertises (9, 2); only B advertises (2, 9); neither advertises (6, 6). Suppose a tax is charged to each firm that advertises, subtracted from its payoff. What is the smallest whole-number tax, in millions, that makes Not advertising a strictly dominant strategy for Firm A (strictly better than advertising whatever Firm B does)?', options: ['\\$3 million', '\\$2 million', '\\$7 million', '\\$4 million'], correctAnswer: 3, explanation: 'With tax t, Not must beat Advertise in both cases: 2 > 4 − t requires t > 2, and 6 > 9 − t requires t > 3, so the smallest whole number is 4. A tax of 3 only creates a tie when B does not advertise, 2 fails both conditions, and 7 works but is not the smallest.', difficulty: 'hard', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 1, part: 1 },
  { question: 'Which statement is true of both monopolistic competition and perfect competition in the long run?', options: ['Firms produce at minimum ATC', 'Price equals marginal cost', 'Firms earn zero economic profit', 'Products are identical'], correctAnswer: 2, explanation: 'Free entry and exit drive economic profit to zero in both structures. Only perfect competition produces at minimum ATC with price equal to MC, and monopolistic competition is defined by differentiated rather than identical products.', difficulty: 'medium', domain: 'imperfect-competition', topicSlug: 'micro-monopolistic-oligopoly', formSet: 2, part: 1 },
  // ── Domain: factor-markets · micro-labor-markets ───────────────────────────────
  { question: 'A competitive firm sells its output for \\$5 per unit. The marginal products of its 1st through 5th workers are 12, 10, 7, 4, and 2 units. If the market wage is \\$30 per day, how many workers should the firm hire?', options: ['4 workers', '3 workers', '2 workers', '5 workers'], correctAnswer: 1, explanation: 'MRP = MP × P gives \\$60, \\$50, \\$35, \\$20, and \\$10. The firm hires every worker whose MRP is at least the \\$30 wage, which is the first three; the 4th worker adds only \\$20. Two workers leaves a profitable hire unmade, and four or five pay workers more than they add.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'A competitive firm sells its output for \\$5 per unit. The marginal products of its 1st through 5th workers are 12, 10, 7, 4, and 2 units. If the market wage falls from \\$30 to \\$15 per day, how many workers should the firm hire?', options: ['4 workers', '3 workers', '5 workers', '2 workers'], correctAnswer: 0, explanation: 'With MRPs of \\$60, \\$50, \\$35, \\$20, and \\$10, the 4th worker\'s \\$20 now exceeds the \\$15 wage, but the 5th worker\'s \\$10 does not. Staying at three ignores the lower wage, hiring five pays more than the 5th worker adds, and two workers was never optimal.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'A firm adds workers while keeping the same amount of equipment. Its demand curve for labor slopes downward mainly because', options: ['the wage must rise to attract more workers', 'the product price rises as output grows', 'fixed costs rise with each new worker hired', 'each added worker adds less output'], correctAnswer: 3, explanation: 'With equipment fixed, diminishing marginal returns mean each additional worker adds less output, so MRP, the firm\'s labor demand, falls as employment rises. A rising wage to attract workers describes labor supply, a competitive firm\'s product price does not rise with its output, and fixed costs do not change with hiring.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'The price of the furniture a firm sells rises substantially. In the competitive market for furniture workers,', options: ['the labor supply curve shifts right, cutting the wage', 'the labor demand curve shifts left, cutting the wage', 'the labor demand curve shifts right, raising the wage', 'the labor market moves along a fixed demand curve'], correctAnswer: 2, explanation: 'A higher product price raises each worker\'s MRP, so firms want more workers at every wage, shifting labor demand right and raising the wage. Workers\' willingness to work is not directly changed, the shift is rightward rather than leftward, and a change in MRP shifts rather than moves along labor demand.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'The price of warehouse robots falls sharply, and the robots can do many of the tasks warehouse workers do. The demand for warehouse workers', options: ['decreases, lowering wages and employment', 'increases, raising wages and employment', 'is unchanged, since robots are capital', 'increases, as robots raise worker output'], correctAnswer: 0, explanation: 'When a substitute input becomes cheaper, firms replace workers with it, so labor demand shifts left. Higher demand would occur if robots were complements that made workers more productive, and capital can still change labor demand when it substitutes for labor.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'Cheaper design software makes each graphic designer able to finish more projects per day. The demand for graphic designers', options: ['falls, since software replaces designers', 'rises, since each designer\'s MRP is higher', 'falls, as fewer designers are now needed', 'is unchanged, as the wage did not change'], correctAnswer: 1, explanation: 'Here the software is a complement: it raises each designer\'s marginal product and therefore MRP, shifting labor demand right. The stem describes higher productivity rather than replacement, a more productive designer is worth more rather than less to the firm, and demand shifts with MRP regardless of the current wage.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'A wave of immigration adds many workers to a region\'s construction labor market, with labor demand unchanged. What happens?', options: ['The wage rises and employment rises', 'The wage falls and employment falls', 'The wage rises and employment falls', 'The wage falls and employment rises'], correctAnswer: 3, explanation: 'More workers shifts labor supply right, which lowers the equilibrium wage and raises the number employed as firms move down their demand curves. A higher wage would require more demand or less supply, and employment rises rather than falls with a supply increase.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'Deep-sea welders earn far more than welders with similar training who work on land. The best explanation is', options: ['higher human capital from more schooling', 'a binding minimum wage in offshore work', 'monopsony power held by offshore employers', 'a compensating differential for risk'], correctAnswer: 3, explanation: 'Dangerous or unpleasant jobs must pay more to attract workers, which is a compensating differential. The workers have similar training, so human capital does not explain the gap; a minimum wage is far below these pay levels; and monopsony power would push wages down, not up.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'A nurse completes extra training that raises her productivity and her pay. The training is an investment in', options: ['physical capital', 'human capital', 'union bargaining power', 'monopsony power'], correctAnswer: 1, explanation: 'Human capital is the knowledge and skill workers gain through education and training, which raises their MRP and wages. Physical capital is machinery and buildings, union bargaining raises pay without raising productivity, and monopsony power belongs to employers.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'An individual firm hiring workers in a perfectly competitive labor market faces a labor supply curve that is', options: ['upward sloping like market supply', 'vertical at its current workforce', 'horizontal at the market wage', 'downward sloping as wages rise'], correctAnswer: 2, explanation: 'A single competitive firm is too small to affect the market wage, so it can hire as many workers as it wants at that wage, a horizontal supply curve. An upward-sloping supply curve faces a monopsonist, a vertical curve would mean no worker responds to pay, and labor supply never slopes downward in this model.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'In a competitive labor market for fast-food workers, the equilibrium wage is \\$13. A city raises its minimum wage from \\$12 to \\$15. Which statement is correct?', options: ['Only the new \\$15 minimum is binding and reduces employment', 'Only the old \\$12 minimum is binding and cuts employment', 'Both minimums are binding and reduce employment', 'Neither minimum is binding, so employment is unchanged'], correctAnswer: 0, explanation: 'A price floor binds only when set above equilibrium: \\$12 is below the \\$13 wage and had no effect, while \\$15 is above it, so firms hire fewer workers. The old minimum could not reduce employment, and the new one is above equilibrium, so it does matter.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'Demand for nurses increases at the same time a new licensing rule reduces the supply of nurses. In the market for nurses, we can expect', options: ['higher employment and an uncertain wage', 'a higher wage and an uncertain level of employment', 'a lower wage and an uncertain level of employment', 'lower employment and an uncertain wage'], correctAnswer: 1, explanation: 'Both shifts push the wage up, so the wage rises for certain. Higher demand pushes employment up while lower supply pushes it down, so the change in employment depends on which shift is larger; neither shift points to a lower wage.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'A labor union negotiates a wage above the competitive equilibrium for workers in its industry. The most likely result is', options: ['more jobs along with higher pay', 'lower pay but more jobs for members', 'no change in the number of jobs', 'higher pay for members but fewer jobs'], correctAnswer: 3, explanation: 'A wage above equilibrium acts like a price floor: those who keep their jobs earn more, but firms move up their labor demand curves and hire fewer workers. Higher pay cannot raise the quantity of labor demanded, the union raised rather than lowered pay, and employment does respond to the wage.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'A competitive firm employs 8 workers at a wage of \\$100 per day. The 8th worker\'s marginal product is 25 units, and the product price falls from \\$4 to \\$3. What should the firm do?', options: ['Keep all 8 workers, as their marginal product is unchanged', 'Employ more workers to offset the lower product price', 'Employ fewer workers, as the 8th now adds only \\$75', 'Cut the wage to \\$75, as the firm sets its own wage'], correctAnswer: 2, explanation: 'The 8th worker\'s MRP falls from 25 × \\$4 = \\$100 to 25 × \\$3 = \\$75, below the \\$100 wage, so the firm should cut employment. MRP depends on price as well as marginal product, hiring more would add workers worth even less, and a competitive firm takes the wage as given.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'A state adds a two-year training requirement to become a licensed electrician. In the market for electricians,', options: ['supply falls, raising the wage and lowering employment', 'demand falls, lowering the wage and employment', 'supply rises, lowering the wage and raising employment', 'demand rises, raising both the wage and employment'], correctAnswer: 0, explanation: 'A licensing requirement reduces the number of qualified workers, shifting labor supply left, which raises the wage and reduces employment. Firms\' demand for electricians is not directly affected, and fewer qualified workers is a supply decrease, not an increase.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  { question: 'Two workers at the same firm do the same job with the same productivity and the same working conditions, yet one is paid less. Which explanation fits these facts?', options: ['Differences in human capital', 'A compensating differential', 'Differences in marginal product', 'Discrimination by the employer'], correctAnswer: 3, explanation: 'When pay differs without any difference in productivity or job conditions, the gap reflects discrimination. Human capital and marginal product differences are ruled out by equal productivity, and a compensating differential requires different working conditions.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 2, part: 1 },
  { question: 'Demand for electric vehicles surges. In the competitive labor market for battery technicians,', options: ['the wage rises but the number employed falls', 'the wage and the number employed both rise', 'the wage falls but the number employed rises', 'the wage and the number employed both fall'], correctAnswer: 1, explanation: 'Labor demand is derived from product demand: a higher price and output for EVs raise technicians\' MRP, shifting labor demand right and raising both the wage and employment. A higher wage with less employment describes a supply decrease, and the other choices reverse the direction of the demand shift.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-labor-markets', formSet: 1, part: 1 },
  // ── Domain: factor-markets · micro-factor-markets ──────────────────────────────
  { question: 'Demand for carpenters falls when new home construction slows. This shows that the demand for labor is', options: ['set by the supply of carpenters', 'fixed regardless of product sales', 'derived from the market for the product', 'determined by the minimum wage'], correctAnswer: 2, explanation: 'Firms hire carpenters only because carpenters produce homes buyers want, so labor demand is a derived demand that falls when product demand falls. Supply does not set demand, labor demand is clearly not fixed here, and a minimum wage would not explain the drop.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'In the circular flow of factor payments, entrepreneurship is rewarded with', options: ['profit', 'interest', 'rent', 'wages'], correctAnswer: 0, explanation: 'Entrepreneurs combine the other factors and bear risk, and their reward is profit. Interest is paid for the use of capital, rent is paid for land, and wages are paid to labor.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'A competitive firm\'s 4th worker raises total output from 30 to 38 units. The product sells for \\$6 per unit. What is the marginal revenue product of the 4th worker?', options: ['\\$228', '\\$8', '\\$180', '\\$48'], correctAnswer: 3, explanation: 'The worker\'s marginal product is 38 − 30 = 8 units, and MRP = MP × P = 8 × \\$6 = \\$48. Two hundred twenty-eight dollars is the revenue from all 38 units, \\$8 is the marginal product without the price, and \\$180 is the revenue from the first 30 units.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'A monopolist\'s 3rd worker adds 10 units of output. Over that range, the firm\'s marginal revenue is \\$4 per unit, while its product price is \\$7. What is the marginal revenue product of the 3rd worker?', options: ['\\$70', '\\$40', '\\$30', '\\$4'], correctAnswer: 1, explanation: 'MRP = MP × MR, and for a firm with market power MR is below price, so MRP = 10 × \\$4 = \\$40. Seventy dollars uses price instead of marginal revenue, which is valid only for a competitive seller; \\$30 multiplies by the gap between price and MR; and \\$4 omits the marginal product.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'A firm can hire workers at \\$120 a day. The MRP of its 9th worker is \\$170, of its 10th worker is \\$150, and of its 11th worker is \\$110. How many workers should it hire?', options: ['10 workers', '11 workers', '9 workers', '12 workers'], correctAnswer: 0, explanation: 'The firm hires while MRP is at least the wage: the 10th worker adds \\$150 for a cost of \\$120, but the 11th adds only \\$110. Stopping at nine gives up \\$30 of profit, and the 11th and 12th workers cost more than they add.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'In a perfectly competitive labor market, a firm\'s marginal factor cost of labor is', options: ['greater than the market wage', 'less than the market wage', 'equal to the market wage', 'equal to MRP at every quantity'], correctAnswer: 2, explanation: 'A wage-taking firm can hire one more worker at the going wage without raising anyone else\'s pay, so MFC equals the wage. MFC above the wage describes a monopsony, MFC is never below the wage, and MRP is the benefit of hiring, not its cost.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'A monopsonist can hire 4 workers at \\$10 an hour each or 5 workers at \\$12 an hour each. What is the marginal factor cost of the 5th worker?', options: ['\\$12', '\\$2', '\\$60', '\\$20'], correctAnswer: 3, explanation: 'Total labor cost rises from 4 × \\$10 = \\$40 to 5 × \\$12 = \\$60, so hiring the 5th worker costs \\$20, because the raise goes to all five. Twelve dollars is only the new wage, \\$2 is only the raise, and \\$60 is total labor cost.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'Compared with a competitive labor market with the same labor supply and MRP curves, a monopsony employer', options: ['pays a lower wage and hires more workers', 'pays a lower wage and hires fewer workers', 'pays a higher wage and hires fewer workers', 'pays a higher wage and hires more workers'], correctAnswer: 1, explanation: 'The monopsonist hires where MRP = MFC, which is fewer workers than where MRP meets supply, and pays the lower wage that the supply curve shows for that number. More hiring or higher pay would describe moving toward the competitive outcome, not away from it.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'A monopsonist finds that MRP equals MFC at 50 workers, where both are \\$22 per hour. The labor supply curve shows that 50 workers will work for \\$15 per hour. What wage does the firm pay?', options: ['\\$22 per hour', '\\$18.50 per hour', '\\$15 per hour', '\\$37 per hour'], correctAnswer: 2, explanation: 'A monopsonist chooses employment where MRP = MFC but pays only the wage needed to attract that many workers, read from the supply curve: \\$15. Twenty-two dollars is the MFC and MRP, which lie above the wage; \\$18.50 averages the two; and \\$37 adds them.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'In a monopsony labor market, a minimum wage set between the monopsony wage and the competitive wage can', options: ['raise both the wage and employment', 'raise the wage but reduce employment', 'lower the wage and reduce employment', 'leave the wage and employment unchanged'], correctAnswer: 0, explanation: 'The minimum wage makes the monopsonist\'s MFC flat at that wage up to the supply curve, so it no longer restricts hiring to hold wages down and employs more workers at the higher wage. Reduced employment is the competitive-market result, a binding minimum cannot lower the wage, and a floor above the monopsony wage does bind.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'A firm uses labor at a wage of \\$20 with a marginal product of 40 units, and capital at a rental price of \\$50 with a marginal product of 50 units. To produce its output at the lowest cost, the firm should', options: ['use more capital and less labor', 'keep its current mix of inputs', 'use more labor and less capital', 'use more of both inputs equally'], correctAnswer: 2, explanation: 'The least-cost rule equates marginal product per dollar: labor gives 40 ÷ 20 = 2 units per dollar and capital gives 50 ÷ 50 = 1, so shifting spending toward labor lowers cost. Shifting toward capital moves the wrong way, the current mix is not cost-minimizing because the ratios differ, and adding both inputs changes output rather than its cost.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'New equipment raises the marginal product of every worker at a competitive firm. The firm\'s MRP curve for labor', options: ['shifts left, so it hires fewer workers', 'shifts right, so it hires more at any wage', 'stays put, as the wage has not changed', 'becomes the firm\'s labor supply curve'], correctAnswer: 1, explanation: 'Higher marginal product raises MRP = MP × P at every level of employment, so the labor demand curve shifts right. A leftward shift would follow lower productivity or a lower product price, the wage affects how many are hired but not the position of MRP, and MRP is the firm\'s demand for labor, not supply.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'On a monopsony graph, the marginal factor cost curve lies above the labor supply curve because', options: ['raising pay to hire one more worker raises pay for all', 'the firm must pay each worker their full MRP', 'the minimum wage sets a floor under all wages', 'workers ask for more as the firm\'s profit rises'], correctAnswer: 0, explanation: 'A monopsonist faces upward-sloping supply, so attracting an additional worker requires a higher wage for every worker already employed, making the added cost exceed the new wage. Workers are not paid their full MRP in monopsony, no minimum wage is assumed, and the curve reflects supply rather than profit.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'Which transaction takes place in a factor market?', options: ['A family buys a new washing machine', 'A student buys a used textbook online', 'A diner sells breakfast to a customer', 'A farm rents an extra acre of land'], correctAnswer: 3, explanation: 'Factor markets are where firms buy or rent land, labor, and capital, so renting land for production is a factor-market transaction. The washing machine, textbook, and breakfast are final goods or services sold to households in product markets.', difficulty: 'easy', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  { question: 'Demand for printed newspapers falls sharply. In the competitive market for printing-press operators, the MRP curve', options: ['shifts right as fewer papers are printed', 'shifts left as the product price drops', 'stays put, since worker MP is unchanged', 'becomes perfectly elastic at the wage'], correctAnswer: 1, explanation: 'Lower demand for newspapers lowers their price, and since MRP = MP × P, each operator\'s MRP falls at every level of employment. Fewer papers means less, not more, demand for operators, MRP changes even if MP does not, and MRP is not horizontal.', difficulty: 'medium', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 1, part: 1 },
  { question: 'A monopsonist can hire 1 worker at \\$8, 2 workers at \\$9 each, 3 at \\$10 each, or 4 at \\$11 each. The MRPs of workers 1 through 4 are \\$20, \\$16, \\$11, and \\$9. How many workers does it hire, and at what wage?', options: ['3 workers at \\$10 each', '2 workers at \\$10 each', '3 workers at \\$12 each', '2 workers at \\$9 each'], correctAnswer: 3, explanation: 'Total labor cost is \\$8, \\$18, \\$30, and \\$44, so MFC is \\$8, \\$10, \\$12, and \\$14; the 2nd worker\'s \\$16 MRP covers its \\$10 MFC, but the 3rd worker\'s \\$11 does not cover \\$12. The firm pays the supply-curve wage for 2 workers, \\$9. Three workers at \\$10 is the competitive outcome, and \\$10 and \\$12 are MFC values, not wages.', difficulty: 'hard', domain: 'factor-markets', topicSlug: 'micro-factor-markets', formSet: 2, part: 1 },
  // ── Domain: market-failure · micro-externalities-public-goods ──────────────────
  { question: 'Which of the following is an example of a negative externality?', options: ['A neighbor\'s loud parties keep you up', 'Your landlord raises your monthly rent', 'A rival applicant gets the job you wanted', 'Concert tickets cost more than last year'], correctAnswer: 0, explanation: 'A negative externality is a cost imposed on a third party outside the transaction, as when a neighbor\'s party costs you sleep. Higher rent and higher ticket prices are price changes within market transactions, and losing a job to a rival is competition, not a spillover cost.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'A paper mill\'s pollution harms people who live downstream, and the mill does not pay for the damage. Compared with the social optimum, the market produces', options: ['an output below the social optimum', 'an output equal to the social optimum', 'an output above the social optimum', 'an output set by the government'], correctAnswer: 2, explanation: 'Because the mill ignores the external cost, its private cost understates the true cost to society, so it produces more paper than is socially optimal. Underproduction results from positive externalities, the market is not efficient here, and no government decision is involved.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'For a good whose production creates a negative externality, the marginal social cost curve', options: ['lies below the marginal private cost curve', 'lies above the marginal private cost curve', 'is identical to the marginal private cost curve', 'crosses demand at the market quantity'], correctAnswer: 1, explanation: 'Marginal social cost equals marginal private cost plus the external cost per unit, so MSC sits above MPC by that amount. MSC below MPC describes a positive production externality, identical curves mean there is no externality, and MSC crosses demand at the smaller, socially optimal quantity.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'Each ton of a chemical produced imposes \\$40 of harm on people near the plant, and the external cost is constant. What per-unit tax would lead the market to the socially optimal output?', options: ['\\$20 per ton', '\\$80 per ton', '\\$4 per ton', '\\$40 per ton'], correctAnswer: 3, explanation: 'A Pigouvian tax equal to the marginal external cost shifts the private cost curve up to the social cost curve, so firms account for the full cost. A smaller tax leaves some external cost ignored, and a larger tax pushes output below the optimum.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'Flu shots protect people who are not vaccinated themselves. Without government action, the market for flu shots', options: ['produces too few shots, since MSB exceeds MPB', 'produces too many shots, since MSB exceeds MPB', 'produces too few shots, since MSC is above MPC', 'produces the efficient number of shots'], correctAnswer: 0, explanation: 'The external benefit to others makes marginal social benefit higher than the private benefit buyers consider, so the market stops short of the optimal quantity. MSB above MPB cannot cause overproduction, MSC above MPC describes a negative externality, and the market is not efficient here.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'College education creates benefits for society beyond those received by the students. To correct the resulting underproduction, the government could', options: ['tax tuition by the amount of the external benefit', 'set a price ceiling on tuition below equilibrium', 'subsidize each student by the external benefit', 'cap student enrollment at the current market quantity'], correctAnswer: 2, explanation: 'A per-unit subsidy equal to the external benefit raises students\' private benefit to match the social benefit, increasing enrollment to the optimal level. A tax would reduce enrollment further, a price ceiling would create a shortage of seats, and capping enrollment locks in the underproduction.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'In a market with a negative production externality, the market output is 500 units and the socially optimal output is 400 units. The external cost is a constant \\$6 per unit. With linear curves, the deadweight loss is', options: ['\\$600', '\\$300', '\\$3,000', '\\$2,400'], correctAnswer: 1, explanation: 'Deadweight loss is the triangle over the overproduced units: ½ × (500 − 400) × \\$6 = \\$300. Six hundred dollars omits the ½, \\$3,000 is the total external cost of all 500 units, and \\$2,400 is the external cost of the optimal 400 units.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'A public good is one that is', options: ['rival and excludable', 'rival but nonexcludable', 'nonrival but excludable', 'nonrival and nonexcludable'], correctAnswer: 3, explanation: 'A public good can be enjoyed by many people at once without being used up, and nonpayers cannot be kept from using it. Rival and excludable describes a private good, rival but nonexcludable a common resource, and nonrival but excludable a club good.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'A fireworks display can be seen by everyone in town. Why will private markets tend to underprovide it?', options: ['One more viewer raises the cost of the display', 'Viewers value the display less than it costs', 'People can enjoy it without paying, so few pay', 'Each viewer uses up part of the display'], correctAnswer: 2, explanation: 'Because no one can be excluded from watching, each person has an incentive to free ride, so voluntary payments fall short of the display\'s value. An extra viewer adds no cost and uses up nothing, since the good is nonrival, and the problem is unpaid value rather than low value.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'Fish in international waters are best classified as', options: ['rival but nonexcludable, a common resource', 'nonrival and nonexcludable, a public good', 'rival and excludable, a private good', 'nonrival but excludable, like cable TV'], correctAnswer: 0, explanation: 'A fish caught by one boat cannot be caught by another, so fish are rival, and no one can be stopped from fishing open waters, so they are nonexcludable, the definition of a common resource. Public goods are nonrival, private goods are excludable, and cable TV is a club good.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'Cattle owners in a village overgraze a shared public pasture until the grass is ruined. Which policy would most directly fix the problem?', options: ['Subsidizing the purchase of more cattle', 'Removing all fees for using the pasture', 'Limiting the cattle each herder may graze', 'Paying herders more for each cow raised'], correctAnswer: 2, explanation: 'Overgrazing is the tragedy of the commons: each herder ignores the cost his cattle impose on others, so a limit on use brings grazing down toward the efficient level. Subsidizing cattle, removing fees, and paying more per cow all encourage even heavier use of the pasture.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'Which statement best describes a toll road that is rarely congested?', options: ['It is nonexcludable and rival', 'It is excludable and nonrival', 'It is excludable and rival', 'It is nonexcludable and nonrival'], correctAnswer: 1, explanation: 'Drivers who do not pay the toll can be kept off the road, so it is excludable, and with little congestion one more car does not reduce anyone else\'s use, so it is nonrival. That makes it a club good rather than a public good, a private good, or a common resource.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'Secondhand smoke harms nonsmokers. On a graph of the cigarette market, the marginal social benefit curve', options: ['lies below the marginal private benefit curve', 'lies above the marginal private benefit curve', 'is the same as the marginal private benefit curve', 'lies above the marginal social cost curve'], correctAnswer: 0, explanation: 'A negative consumption externality means society gains less from each pack than smokers do, so MSB is below MPB (the demand curve) and the market overconsumes. MSB above MPB would be a positive consumption externality, identical curves mean no externality, and MSB above MSC at every quantity would mean more consumption is always better.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'A per-unit tax equal to the marginal external cost is placed on a good whose production pollutes. The tax', options: ['raises output to the socially optimal level', 'eliminates all pollution from the market', 'lowers the price that buyers must pay', 'moves output to the socially optimal level'], correctAnswer: 3, explanation: 'The tax makes producers face the full social cost, shifting supply up to the MSC curve, so output falls to the efficient quantity. Output falls rather than rises, the efficient level still has some pollution, and buyers pay a higher price, not a lower one.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  { question: 'A beekeeper\'s bees pollinate a neighboring apple orchard for free, raising the orchard\'s harvest. In the market for honey,', options: ['output is too high, since MSC is below MPC', 'output is too low, since MSC lies above MPC', 'output is efficient, since honey is a private good', 'output is too low, since MSC is below MPC'], correctAnswer: 3, explanation: 'The pollination is a positive production externality: part of the beekeeper\'s cost is offset by benefits to the orchard, so the social cost of honey is below the private cost and the market produces too little. MSC below MPC cannot cause overproduction, MSC above MPC would be a negative externality, and honey being private does not remove the spillover.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 1, part: 1 },
  { question: 'A factory\'s marginal private cost at its current output is \\$50, and each unit causes \\$15 of harm to neighbors. What is the marginal social cost?', options: ['\\$35', '\\$65', '\\$50', '\\$15'], correctAnswer: 1, explanation: 'Marginal social cost is the private cost plus the external cost, \\$50 + \\$15 = \\$65. Thirty-five dollars subtracts the harm instead of adding it, \\$50 is only the private cost, and \\$15 is only the external cost.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-externalities-public-goods', formSet: 2, part: 1 },
  // ── Domain: market-failure · micro-market-failure ──────────────────────────────
  { question: 'A town\'s only cable company restricts its output to raise prices. This inefficiency stems from', options: ['market power', 'a public good', 'an externality', 'a common resource'], correctAnswer: 0, explanation: 'A single seller with no close competitors can hold output below the efficient level and raise prices, a market failure caused by market power. Public goods, positive externalities, and common resources involve spillovers or nonexcludability, not a firm\'s control over price.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'Which condition shows that a market is producing the efficient quantity from society\'s point of view?', options: ['Marginal private benefit exceeds marginal private cost', 'Total revenue equals total cost for every firm', 'Marginal social benefit equals marginal social cost', 'Consumer surplus equals producer surplus in size'], correctAnswer: 2, explanation: 'The socially optimal quantity is where the benefit to society of the last unit equals its cost to society. Private benefit above private cost means more units should be produced, zero profit for firms is not the efficiency test, and the sizes of consumer and producer surplus need not be equal.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'A firm is productively efficient when it', options: ['sets price equal to its marginal cost', 'earns the largest profit it can', 'produces at the minimum of its ATC', 'produces where MR equals its MC'], correctAnswer: 2, explanation: 'Productive efficiency means producing at the lowest possible average total cost. Price equal to MC is the condition for allocative efficiency, and profit maximization at MR = MC does not guarantee the lowest average cost.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'A market produces 500 units of a good, but marginal social benefit equals marginal social cost at 400 units. Which statement is correct?', options: ['The market is efficient because buyers chose 500 units', 'A deadweight loss arises from the 100 extra units', 'A deadweight loss arises from the 100 missing units', 'Total surplus is maximized at the 500 units made'], correctAnswer: 1, explanation: 'Any quantity other than the one where MSB = MSC creates deadweight loss. Here the market overproduces: each of the 100 units beyond 400 costs society more than it is worth, so total surplus is not maximized at 500, and no units are missing.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'Which pairing of a market failure with a government response is most appropriate?', options: ['Pollution and a per-unit tax on output', 'Education and a per-unit tax on tuition', 'National defense and a fee on each user', 'Monopoly and a guaranteed minimum price'], correctAnswer: 0, explanation: 'A per-unit tax on a polluting good raises its private cost to its social cost and reduces overproduction. Taxing education would shrink a good with external benefits, charging users of national defense is impossible because it is nonexcludable, and a price floor would not fix a monopoly\'s high price.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'A profit-maximizing monopolist must pay a one-time \\$50,000 license fee that does not depend on how much it produces. Its price and output', options: ['both rise to cover the license fee', 'stay the same, while its earnings drop', 'price rises while its output falls', 'price falls while its output rises'], correctAnswer: 1, explanation: 'A lump-sum fee is a fixed cost, so it does not change marginal cost or marginal revenue, and the profit-maximizing output where MR = MC stays the same. The firm simply earns \\$50,000 less profit; raising price would mean moving off its profit-maximizing point.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'A per-unit tax on a monopolist\'s output, unlike a lump-sum tax of the same total amount, will', options: ['leave its price and output unchanged', 'lower its price and raise its output', 'reduce its profit but leave output alone', 'raise its price and reduce its output'], correctAnswer: 3, explanation: 'A per-unit tax raises the monopolist\'s marginal cost, so the MR = MC point moves to a smaller quantity sold at a higher price. Leaving price and output unchanged is the effect of a lump-sum tax, and higher marginal cost cannot lead to more output.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'Antitrust laws are designed mainly to correct which problem?', options: ['the underprovision of public goods', 'the overuse of common resources', 'the misuse of market power', 'pollution from production'], correctAnswer: 2, explanation: 'Antitrust policy blocks mergers and practices that create or abuse monopoly power, which restricts output and raises prices. Public goods are addressed by government provision, common resources by quotas or property rights, and pollution by taxes or regulation.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'Which government action would move a market with a positive consumption externality toward the efficient quantity?', options: ['A per-unit subsidy to buyers of the good', 'A per-unit tax on buyers of the good', 'A price floor above the market price', 'A quota limiting how much can be sold'], correctAnswer: 0, explanation: 'A positive consumption externality means buyers consume too little, and a subsidy raises their private benefit so consumption increases. A tax, a binding price floor, and a quota would all reduce consumption further.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'On a Lorenz curve diagram, the 45-degree line represents', options: ['complete income inequality', 'perfect income equality', 'the actual income distribution', 'the official poverty line'], correctAnswer: 1, explanation: 'Along the 45-degree line, each percentage of households receives the same percentage of income, which is perfect equality. Perfect inequality hugs the bottom and right axes, the actual distribution is the bowed Lorenz curve itself, and the diagram does not show a poverty line.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'Country A has a Gini coefficient of 0.25, and Country B has a Gini coefficient of 0.45. Which statement is correct?', options: ['Income is more equally distributed in A', 'B has the more equal income distribution', 'A has a higher average income than B', 'B\'s Lorenz curve is closer to equality'], correctAnswer: 0, explanation: 'A lower Gini coefficient means the Lorenz curve is closer to the line of equality, so income is more equally distributed in A. The Gini coefficient measures distribution rather than the level of income, and B\'s higher value means its Lorenz curve bows farther from equality.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'A tax takes 10 percent of income from a household earning \\$20,000 and 5 percent from a household earning \\$200,000. This tax is', options: ['progressive', 'proportional', 'lump-sum', 'regressive'], correctAnswer: 3, explanation: 'A regressive tax takes a smaller percentage of income as income rises. A progressive tax takes a larger percentage from higher earners, a proportional tax takes the same percentage from everyone, and a lump-sum tax charges the same dollar amount, which is not the case here.', difficulty: 'easy', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'A government raises income taxes on high earners and expands cash transfers to low-income households. What happens to the Lorenz curve and the Gini coefficient?', options: ['The Lorenz curve moves away from the line of equality and the Gini rises', 'The Lorenz curve moves toward the line of equality and the Gini rises', 'The Lorenz curve moves toward the line of equality and the Gini falls', 'The Lorenz curve moves away from the line of equality and the Gini falls'], correctAnswer: 2, explanation: 'Shifting after-tax income from high to low earners makes the distribution more equal, so the Lorenz curve moves closer to the 45-degree line and the Gini coefficient, which measures the gap, falls. The Gini and the curve always move together, so a curve closer to equality cannot come with a higher Gini.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'Which of the following is NOT a market failure in the economic sense, even though many people may consider it unfair?', options: ['A factory\'s smoke harms nearby farms without payment', 'Efficient outcomes leave some households with low incomes', 'Residents won\'t fund a streetlight they would all use', 'A sole supplier restricts output to raise its price'], correctAnswer: 1, explanation: 'Market failure means resources are allocated inefficiently; an efficient outcome can still produce an unequal income distribution, which raises equity rather than efficiency concerns. Unpaid smoke damage is a negative externality, the unfunded streetlight is a public-good problem, and restricted output is market power.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
  { question: 'Which of the following is most likely to widen income inequality in a market economy?', options: ['A more progressive income tax system', 'Larger cash transfers to poor families', 'A bigger tax credit for low-wage earners', 'Rising pay for skills that few workers have'], correctAnswer: 3, explanation: 'When the market rewards scarce skills more highly, earnings grow fastest for those who already have the most human capital, widening the income gap. A more progressive tax, larger transfers, and tax credits for low earners all redistribute income toward the bottom and narrow inequality.', difficulty: 'medium', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 1, part: 1 },
  { question: 'A regulator imposes a price ceiling on an unregulated monopolist at the price where its marginal cost curve crosses the demand curve. Compared with the unregulated outcome,', options: ['output falls and deadweight loss grows larger', 'output rises and deadweight loss is eliminated', 'price and output both stay unchanged', 'price rises above the monopoly level'], correctAnswer: 1, explanation: 'At the ceiling, the monopolist\'s marginal revenue becomes the ceiling price up to the demand curve, so it produces where MC equals that price, the allocatively efficient quantity. The ceiling is below the monopoly price, so it binds, lowers price, and raises output rather than reducing it.', difficulty: 'hard', domain: 'market-failure', topicSlug: 'micro-market-failure', formSet: 2, part: 1 },
]

export function generateExitQuiz(count = 10, topicSlug?: string): { id: string; question: string; options: string[]; correctIndex: number; explanation: string; category: string }[] {
  let pool = microQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  return shuffleArray(pool).slice(0, count).map((q, i) => ({
    id: `${q.topicSlug}-q${i}`,
    question: q.question,
    options: q.options,
    correctIndex: q.correctAnswer,
    explanation: q.explanation,
    category: q.domain,
    topicSlug: q.topicSlug,
    partNumber: q.part,
  }))
}
